    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat untuk melengkapi kalimat: 新規プロジェクトの___にあたり、関係者に資料を配布した。', '{"options":["実施","欠席","撤退","妥協"],"translation":"Menjelang pelaksanaan proyek baru, materi telah dibagikan kepada pihak terkait.","sentence_template":"新規プロジェクトの[blank]にあたり、関係者に資料を配布した。"}'::jsonb, '{"selected":"実施"}'::jsonb, '実施 (jisshi) berarti pelaksanaan atau implementasi resmi suatu proyek atau kebijakan.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 社長から今期の営業___について詳しい説明があった。', '{"options":["方針","気候","趣味","景色"],"translation":"Ada penjelasan rinci dari direktur utama mengenai kebijakan penjualan periode ini.","sentence_template":"社長から今期の営業[blank]について詳しい説明があった。"}'::jsonb, '{"selected":"方針"}'::jsonb, '方針 (houshin) berarti arah kebijakan atau pedoman strategis perusahaan.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 式典の___に先立ち、司会者が注意事項を案内した。', '{"options":["開会","解散","閉店","休暇"],"translation":"Sebelum pembukaan upacara, pembawa acara menyampaikan hal-hal yang perlu diperhatikan.","sentence_template":"式典の[blank]に先立ち、司会者が注意事項を案内した。"}'::jsonb, '{"selected":"開会"}'::jsonb, '開会 (kaikai) berarti pembukaan rapat, seminar, atau upacara resmi.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman pembukaan rapat berikut. Apa yang disampaikan oleh pembicara?', '{"audio_text":"会議の開会にあたり、まずは皆様のご協力に心より感謝申し上げます。","options":[{"id":"opt_1","text":"Mengucapkan terima kasih atas kerja sama para peserta rapat"},{"id":"opt_2","text":"Meminta peserta segera meninggalkan ruang rapat"},{"id":"opt_3","text":"Mengumumkan bahwa rapat ditunda hingga minggu depan"},{"id":"opt_4","text":"Menanyakan daftar menu makan siang setelah rapat"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'Frasa ご協力に心より感謝申し上げます adalah ungkapan terima kasih yang sangat sopan di awal acara resmi.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Dokumen apa yang sedang dibahas?', '{"audio_text":"新しい契約を結ぶ前に、法務部で細かい条件を確認する必要があります。","options":[{"id":"opt_1","text":"Jadwal liburan karyawan tahunan"},{"id":"opt_2","text":"Ketentuan rinci dalam kontrak baru"},{"id":"opt_3","text":"Laporan kerusakan mesin pabrik"},{"id":"opt_4","text":"Daftar hadir mahasiswa tingkat akhir"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '契約を結ぶ (menandatangani kontrak) dan 細かい条件を確認する (memeriksa ketentuan rinci) adalah kosakata inti bisnis N2.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih banyak atas kerja sama Anda semua dalam proyek ini."', '{"display_text":"本プロジェクトへのご協力、誠にありがとうございます。","romaji":"Hon purojekuto e no gokyouryoku, makoto ni arigatou gozaimasu.","phonetic_breakdown":["ほん","ぷろじぇくと","えの","ごきょうりょく","まことに","ありがとうございます"]}'::jsonb, '{"expected_transcript":"本プロジェクトへのご協力、誠にありがとうございます。"}'::jsonb, '誠に (makoto ni) jauh lebih formal daripada 本当に dan sering dipakai dalam pidato atau email bisnis.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pola tata bahasa N2: 新支社を設立する___、現地の市場調査を徹底的に行った。', '{"options":["にあたって","に限らず","にもかかわらず","かねない"],"translation":"Menjelang pendirian kantor cabang baru, kami melakukan riset pasar lokal secara menyeluruh.","sentence_template":"新支社を設立する[blank]、現地の市場調査を徹底的に行った。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, 'V-dict + にあたって menyatakan momen penting yang akan dimulai dan persiapan yang dilakukan.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang paling formal untuk pidato: 開会式を始める___、一言ご挨拶申し上げます。', '{"options":["にあたり","に伴って","つつあり","ざるを得ず"],"translation":"Pada kesempatan dimulainya upacara pembukaan, izinkan saya menyampaikan sepatah kata sambutan.","sentence_template":"開会式を始める[blank]、一言ご挨拶申し上げます。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, '～にあたり adalah bentuk tulisan/pidato yang lebih ringkas dan formal dari ～にあたって.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 留学生活の開始___、必要な手続きを確認しておこう。', '{"options":["にあたって","においての","にしては","にわたって"],"translation":"Menjelang dimulainya kehidupan studi di luar negeri, mari kita pastikan prosedur yang diperlukan.","sentence_template":"留学生活の開始[blank]、必要な手続きを確認しておこう。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, 'Kata benda (開始) dapat langsung diikuti にあたって untuk menyatakan ''menjelang dimulainya...''.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang pelaksanaan acara, kami mengadakan rapat terakhir."', '{"tokens":["イベントの","打ち合わせを","最終","にあたって、","実施","行った。","かねない。","にもかかわらず、"],"target_translation":"Menjelang pelaksanaan acara, kami mengadakan rapat terakhir.","romaji":"Ibento no jisshi ni atatte, saishuu uchiawase o okonatta."}'::jsonb, '["イベントの","実施","にあたって、","最終","打ち合わせを","行った。"]'::jsonb, 'Pola [Kata Benda] + にあたって menghubungkan momen penting dengan persiapan konkret.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam rangka peluncuran produk baru, kami menyusun strategi pemasaran."', '{"tokens":["にあたり、","立てた。","発売した","に限らず、","戦略を","新製品を","販売","発売する"],"target_translation":"Dalam rangka peluncuran produk baru, kami menyusun strategi pemasaran.","romaji":"Shinseihin o hatsubai suru ni atari, hanbai senryaku o tateta."}'::jsonb, '["新製品を","発売する","にあたり、","販売","戦略を","立てた。"]'::jsonb, 'Sebelum にあたり, verba selalu memakai bentuk kamus (発売する), bukan bentuk lampau.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang dimulainya kuliah semester baru, saya membeli buku referensi."', '{"display_text":"新学期の開始にあたって、参考書を購入しました。","romaji":"Shingakki no kaishi ni atatte, sankousho o kounyuu shimashita.","phonetic_breakdown":["しんがっきの","かいしに","あたって","さんこうしょを","こうにゅうしました"]}'::jsonb, '{"expected_transcript":"新学期の開始にあたって、参考書を購入しました。"}'::jsonb, '購入する (kounyuu suru) adalah padanan formal dari 買う yang cocok dipasangkan dengan ～にあたって.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan berikut. Apa tujuan dari panduan yang dibuat?', '{"audio_text":"新システムの導入にあたり、全社員向けの操作マニュアルを作成しました。","options":[{"id":"opt_1","text":"Memandu seluruh karyawan mengoperasikan sistem baru"},{"id":"opt_2","text":"Mengumumkan penutupan sementara kantor pusat"},{"id":"opt_3","text":"Menawarkan pelatihan bahasa asing secara sukarela"},{"id":"opt_4","text":"Mengganti seluruh komputer kantor pada akhir tahun"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '導入にあたり (menjelang adopsi sistem baru) diikuti pembuatan 操作マニュアル (panduan pengoperasian).', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan sambutan wisuda berikut. Kapan pembicara menyampaikan pesan ini?', '{"audio_text":"卒業式にあたり、これまで支えてくださった先生方に深く御礼申し上げます。","options":[{"id":"opt_1","text":"Saat mendaftar ujian masuk universitas"},{"id":"opt_2","text":"Saat menghadiri wawancara kerja pertama"},{"id":"opt_3","text":"Pada kesempatan upacara kelulusan"},{"id":"opt_4","text":"Ketika menyerahkan laporan praktikum"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '卒業式にあたり berarti ''pada kesempatan upacara kelulusan'', momen positif yang cocok dengan ～にあたり.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan informasi seminar berikut. Apa yang harus disiapkan peserta?', '{"audio_text":"国際会議への参加にあたっては、事前のオンライン登録と発表資料の提出が必要です。","options":[{"id":"opt_1","text":"Membawa paspor asli ke ruang seminar"},{"id":"opt_2","text":"Membayar biaya pendaftaran di lokasi acara"},{"id":"opt_3","text":"Mengikuti tes wawancara sebelum masuk"},{"id":"opt_4","text":"Melakukan registrasi daring dan menyerahkan materi presentasi"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '事前のオンライン登録 (registrasi daring sebelumnya) dan 発表資料の提出 (penyerahan materi presentasi) adalah syarat yang disebutkan.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Baca kutipan pengumuman berikut lalu lengkapi: 引っ越しをする___、市役所で転出届を出す必要がある。', '{"options":["にあたって","つつある","わけにはいかず","に伴って"],"translation":"Menjelang pindah rumah, perlu mengajukan surat keterangan pindah di balai kota.","sentence_template":"引っ越しをする[blank]、市役所で転出届を出す必要がある。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, 'Pindah rumah adalah peristiwa penting yang memerlukan prosedur resmi, sehingga tepat memakai ～にあたって.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi teks memo internal: 来月の監査を___にあたり、各部署で書類の整理を進めてください。', '{"options":["迎える","迎えた","迎えて","迎えない"],"translation":"Menjelang menghadapi audit bulan depan, mohon tiap departemen melanjutkan perapian dokumen.","sentence_template":"来月の監査を[blank]にあたり、各部署で書類の整理を進めてください。"}'::jsonb, '{"selected":"迎える"}'::jsonb, 'Di depan にあたり, kata kerja selalu memakai bentuk kamus (迎える).', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pada kesempatan pembukaan seminar hari ini, kami ucapkan selamat datang."', '{"display_text":"本日のセミナー開会にあたり、皆様を心より歓迎いたします。","romaji":"Honjitsu no seminaa kaikai ni atari, minasama o kokoro yori kangei itashimasu.","phonetic_breakdown":["ほんじつの","せみなー","かいかいに","あたり","みなさまを","こころより","かんげいいたします"]}'::jsonb, '{"expected_transcript":"本日のセミナー開会にあたり、皆様を心より歓迎いたします。"}'::jsonb, '歓迎いたします adalah bentuk kenjougo sopan untuk menyambut tamu atau peserta seminar.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang penandatanganan kontrak, mari kita periksa ulang jadwalnya."', '{"tokens":["締結した","締結","再確認","にもかかわらず、","契約の","しましょう。","にあたって、","日程を"],"target_translation":"Menjelang penandatanganan kontrak, mari kita periksa ulang jadwalnya.","romaji":"Keiyaku no teiketsu ni atatte, nittei o saikakunin shimashou."}'::jsonb, '["契約の","締結","にあたって、","日程を","再確認","しましょう。"]'::jsonb, '締結 (teiketsu) berarti penandatanganan/pengesahan kontrak secara resmi.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam rangka ekspansi ke luar negeri, kami merekrut tenaga ahli."', '{"tokens":["にあたり、","海外へ","専門家を","進出して","進出する","採用","かねない","した。"],"target_translation":"Dalam rangka ekspansi ke luar negeri, kami merekrut tenaga ahli.","romaji":"Kaigai e shinshutsu suru ni atari, senmonka o saiyou shita."}'::jsonb, '["海外へ","進出する","にあたり、","専門家を","採用","した。"]'::jsonb, '進出する (melakukan ekspansi pasar) + にあたり menyatakan persiapan strategis sebelum ekspansi.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang ujian kelulusan, mahasiswa berdiskusi dengan dosen pembimbing."', '{"tokens":["にあたって、","指導教員と","卒業試験を","に限らず、","相談","受ける","した。","受けた"],"target_translation":"Menjelang ujian kelulusan, mahasiswa berdiskusi dengan dosen pembimbing.","romaji":"Sotsugyou shiken o ukeru ni atatte, shidou kyouin to soudan shita."}'::jsonb, '["卒業試験を","受ける","にあたって、","指導教員と","相談","した。"]'::jsonb, '指導教員 (dosen pembimbing) adalah kosakata penting bagi mahasiswa Indonesia di universitas Jepang.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang kerja sama ini, saya ingin menjelaskan jadwal pelaksanaannya."', '{"display_text":"今回の提携にあたって、実施スケジュールをご説明いたします。","romaji":"Konkai no teikei ni atatte, jisshi sukejuuru o gosetsumei itashimasu.","phonetic_breakdown":["こんかいの","ていけいに","あたって","じっし","すけじゅーるを","ごせつめいいたします"]}'::jsonb, '{"expected_transcript":"今回の提携にあたって、実施スケジュールをご説明いたします。"}'::jsonb, '提携 (teikei) berarti aliansi atau kerja sama bisnis antarperusahaan.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pada kesempatan pindah tugas ke Tokyo, saya mengucapkan banyak terima kasih."', '{"display_text":"東京への転勤にあたり、これまでのご支援に感謝いたします。","romaji":"Toukyou e no tenkin ni atari, kore made no goshien ni kansha itashimasu.","phonetic_breakdown":["とうきょうえの","てんきんに","あたり","これまでの","ごしえんに","かんしゃいたします"]}'::jsonb, '{"expected_transcript":"東京への転勤にあたり、これまでのご支援に感謝いたします。"}'::jsonb, '転勤 (tenkin) adalah mutasi kerja; ungkapan ini sangat alami untuk email perpisahan kantor.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang pembukaan cabang baru, kami sedang melatih staf lokal."', '{"display_text":"新店舗の開店にあたって、現地スタッフの研修を行っています。","romaji":"Shintenpo no kaiten ni atatte, genchi sutaffu no kenshuu o okonatte imasu.","phonetic_breakdown":["しんてんぽの","かいてんに","あたって","げんちすたっふの","けんしゅうを","おこなっています"]}'::jsonb, '{"expected_transcript":"新店舗の開店にあたって、現地スタッフの研修を行っています。"}'::jsonb, '研修を行う (menyelenggarakan pelatihan) lazim dipakai dalam persiapan operasional bisnis.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kalimat yang tepat secara tata bahasa N2: 新規事業を立ち上げる___、十分な資金計画が不可欠だ。', '{"options":["にあたって","に伴いながら","ざるを得ない","わけにはいかない"],"translation":"Menjelang merintis bisnis baru, rencana pendanaan yang memadai sangatlah mutlak diperlukan.","sentence_template":"新規事業を立ち上げる[blank]、十分な資金計画が不可欠だ。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, '立ち上げる (merintis/meluncurkan) + にあたって menyatakan momen awal penting yang butuh persiapan.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 調査報告書を作成する___、データの正確性を何度も検証した。', '{"options":["にあたり","かねなく","つつあり","にもかかわらず"],"translation":"Dalam rangka menyusun laporan hasil survei, kami memverifikasi keakuratan data berkali-kali.","sentence_template":"調査報告書を作成する[blank]、データの正確性を何度も検証した。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, '～にあたり dapat diikuti tindakan persiapan teliti seperti 検証した (memverifikasi).', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pernyataan manajer proyek berikut. Apa prioritas utama sebelum proyek dimulai?', '{"audio_text":"大型プロジェクトの開始にあたり、まずはチーム内の連絡体制を明確にしておきたい。","options":[{"id":"opt_1","text":"Memperjelas sistem komunikasi di dalam tim"},{"id":"opt_2","text":"Mengurangi jumlah anggota tim secara bertahap"},{"id":"opt_3","text":"Memindahkan kantor proyek ke kota lain"},{"id":"opt_4","text":"Membatalkan rapat mingguan selama sebulan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '連絡体制を明確にする berarti memperjelas alur/sistem komunikasi internal tim.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pesan rektor berikut. Kepada siapa pesan ini ditujukan?', '{"audio_text":"入学式にあたり、新入生の皆さんが充実した大学生活を送られることを願っております。","options":[{"id":"opt_1","text":"Para alumni yang telah bekerja sepuluh tahun"},{"id":"opt_2","text":"Para mahasiswa baru pada upacara penerimaan"},{"id":"opt_3","text":"Para staf administrasi perpustakaan kampus"},{"id":"opt_4","text":"Para tamu undangan dari pemerintah daerah"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '入学式にあたり (pada kesempatan upacara masuk) dan 新入生の皆さん (para mahasiswa baru) adalah petunjuk utamanya.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang penerbitan buku, penulis memeriksa seluruh naskah."', '{"tokens":["著者は","出版","にあたり、","書籍の","全原稿を","出版して","かねない。","確認した。"],"target_translation":"Menjelang penerbitan buku, penulis memeriksa seluruh naskah.","romaji":"Shoseki no shuppan ni atari, chosha wa zengenkou o kakunin shita."}'::jsonb, '["書籍の","出版","にあたり、","著者は","全原稿を","確認した。"]'::jsonb, '原稿 (genkou) adalah naskah; 出版にあたり berarti menjelang/dalam rangka penerbitan.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam rangka memulai kerja sama baru, mohon bimbingan dan dukungannya."', '{"display_text":"新たな取引の開始にあたり、今後ともよろしくお願い申し上げます。","romaji":"Aratana torihiki no kaishi ni atari, kongo tomo yoroshiku onegai moushiagemasu.","phonetic_breakdown":["あらたな","とりひきの","かいしに","あたり","こんごとも","よろしくおねがい","もうしあげます"]}'::jsonb, '{"expected_transcript":"新たな取引の開始にあたり、今後ともよろしくお願い申し上げます。"}'::jsonb, '取引 (torihiki) adalah transaksi/hubungan bisnis; よろしくお願い申し上げます adalah penutup bisnis paling sopan.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk berita ekonomi: 原材料費の高騰により、食品の___が上昇している。', '{"options":["物価","挨拶","契約","礼儀"],"translation":"Akibat lonjakan biaya bahan baku, harga bahan pangan sedang meningkat.","sentence_template":"原材料費の高騰により、食品の[blank]が上昇している。"}'::jsonb, '{"selected":"物価"}'::jsonb, '物価 (bukka) berarti tingkat harga barang-barang kebutuhan secara umum.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang teknologi: スマートフォンの___により、オンライン決済が一般的になった。', '{"options":["普及","延期","欠席","妥協"],"translation":"Berkat meluasnya penggunaan ponsel pintar, pembayaran daring menjadi hal yang umum.","sentence_template":"スマートフォンの[blank]により、オンライン決済が一般的になった。"}'::jsonb, '{"selected":"普及"}'::jsonb, '普及 (fukyuu) berarti penyebaran luas suatu teknologi atau kebiasaan di masyarakat.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah demografi yang tepat: 日本では___が進み、労働力不足が深刻化している。', '{"options":["少子高齢化","国際交流","観光開発","語学学習"],"translation":"Di Jepang, penurunan angka kelahiran dan penuaan penduduk terus berlanjut sehingga kekurangan tenaga kerja makin serius.","sentence_template":"日本では[blank]が進み、労働力不足が深刻化している。"}'::jsonb, '{"selected":"少子高齢化"}'::jsonb, '少子高齢化 (shoushi koureika) adalah istilah berita N2 yang sangat sering muncul.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan berita berikut. Apa yang sedang meningkat?', '{"audio_text":"リモートワークの普及に伴って、地方へ移住する若者が増加しています。","options":[{"id":"opt_1","text":"Jumlah anak muda yang pindah ke daerah"},{"id":"opt_2","text":"Harga tiket kereta cepat antarkota"},{"id":"opt_3","text":"Jumlah kantor baru di pusat kota Tokyo"},{"id":"opt_4","text":"Jam kerja lembur di perusahaan manufaktur"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '地方へ移住する若者が増加 (anak muda yang pindah ke daerah meningkat) terjadi seiring meluasnya kerja jarak jauh.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan laporan pasar berikut. Mengapa permintaan energi meningkat?', '{"audio_text":"データセンターの拡大に伴い、電力の需要が急激に高まっています。","options":[{"id":"opt_1","text":"Karena musim dingin berlangsung lebih lama"},{"id":"opt_2","text":"Karena ekspansi pusat data"},{"id":"opt_3","text":"Karena tarif listrik diturunkan setengahnya"},{"id":"opt_4","text":"Karena pabrik mobil listrik baru dibuka"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'データセンターの拡大 (ekspansi pusat data) menyebabkan 電力の需要 (permintaan listrik) melonjak.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring perkembangan teknologi, cara kita bekerja pun berubah drastis."', '{"display_text":"技術の発展に伴って、私たちの働き方も大きく変わりました。","romaji":"Gijutsu no hatten ni tomonatte, watashitachi no hatarakikata mo ookiku kawarimashita.","phonetic_breakdown":["ぎじゅつの","はってんに","ともなって","わたしたちの","はたらきかたも","おおきく","かわりました"]}'::jsonb, '{"expected_transcript":"技術の発展に伴って、私たちの働き方も大きく変わりました。"}'::jsonb, '発展 (hatten) berarti perkembangan; 働き方 (hatarakikata) berarti cara/gaya bekerja.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pola perubahan beriringan: 都市の人口が増加する___、交通渋滞がひどくなっている。', '{"options":["に伴って","にあたって","に限らず","わけにはいかず"],"translation":"Seiring meningkatnya populasi kota, kemacetan lalu lintas menjadi makin parah.","sentence_template":"都市の人口が増加する[blank]、交通渋滞がひどくなっている。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, 'V-dict + に伴って menyatakan perubahan B yang terjadi seiring perubahan A.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk menerangkan kata benda di belakangnya: 経済成長___環境問題への対策が急がれている。', '{"options":["に伴う","に伴って","に伴い","にあたって"],"translation":"Langkah penanggulangan masalah lingkungan yang menyertai pertumbuhan ekonomi sedang dipercepat.","sentence_template":"経済成長[blank]環境問題への対策が急がれている。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, 'Saat langsung menerangkan kata benda (環境問題), gunakan bentuk ～に伴う.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat bergaya berita formal: 法律の改正___、新しい申請手続きが導入された。', '{"options":["に伴い","かねない","つつある","ざるを得ない"],"translation":"Seiring revisi undang-undang, prosedur pengajuan baru telah diterapkan.","sentence_template":"法律の改正[blank]、新しい申請手続きが導入された。"}'::jsonb, '{"selected":"に伴い"}'::jsonb, '～に伴い adalah bentuk tulis/formal dari ～に伴って yang lazim dalam artikel berita dan pengumuman resmi.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seiring meningkatnya wisatawan asing, informasi multibahasa diperluas."', '{"tokens":["にあたって、","多言語案内が","外国人観光客の","に伴って、","拡充","増加して","増加","された。"],"target_translation":"Seiring meningkatnya wisatawan asing, informasi multibahasa diperluas.","romaji":"Gaikokujin kankoukyaku no zouka ni tomonatte, tagengo annai ga kakujuu sareta."}'::jsonb, '["外国人観光客の","増加","に伴って、","多言語案内が","拡充","された。"]'::jsonb, '拡充される (diperluas/ditingkatkan cakupannya) sangat alami berpasangan dengan 増加に伴って.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seiring kemajuan AI, pekerjaan baru bermunculan."', '{"tokens":["に伴い、","生まれている。","進歩した","進歩","にもかかわらず、","AIの","職業が","新しい"],"target_translation":"Seiring kemajuan AI, pekerjaan baru bermunculan.","romaji":"Eiai no shinpo ni tomonai, atarashii shokugyou ga umarete iru."}'::jsonb, '["AIの","進歩","に伴い、","新しい","職業が","生まれている。"]'::jsonb, '進歩 (kemajuan) + に伴い menyatakan perubahan sosial yang menyertai kemajuan teknologi.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring pemulihan ekonomi, perekrutan karyawan baru pun bertambah."', '{"display_text":"景気の回復に伴って、新卒採用の数も増えています。","romaji":"Keiki no kaifuku ni tomonatte, shinsotsu saiyou no kazu mo fuete imasu.","phonetic_breakdown":["けいきの","かいふくに","ともなって","しんそつ","さいようの","かずも","ふえています"]}'::jsonb, '{"expected_transcript":"景気の回復に伴って、新卒採用の数も増えています。"}'::jsonb, '景気の回復 (pemulihan ekonomi) dan 新卒採用 (perekrutan lulusan baru) adalah istilah populer dunia kerja Jepang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan berita berikut. Dampak apa yang muncul akibat pembangunan stasiun baru?', '{"audio_text":"新駅の開業に伴い、周辺の地価やマンションの家賃が上昇している。","options":[{"id":"opt_1","text":"Harga tanah dan sewa apartemen di sekitarnya naik"},{"id":"opt_2","text":"Jumlah penumpang bus antarkota meningkat tajam"},{"id":"opt_3","text":"Sekolah dasar di sekitar stasiun ditutup sementara"},{"id":"opt_4","text":"Lahan parkir gratis ditambah di pusat perbelanjaan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '周辺の地価 (harga tanah sekitar) dan 家賃 (biaya sewa) naik seiring pembukaan stasiun baru (新駅の開業).', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar analis berikut. Mengapa perusahaan memperbarui sistem keamanan?', '{"audio_text":"クラウドサービスの利用拡大に伴って、サイバー攻撃のリスクも高まっているためです。","options":[{"id":"opt_1","text":"Karena biaya langganan server turun drastis"},{"id":"opt_2","text":"Karena risiko serangan siber naik seiring meluasnya layanan cloud"},{"id":"opt_3","text":"Karena karyawan diminta bekerja tanpa internet"},{"id":"opt_4","text":"Karena kontrak dengan penyedia lama telah berakhir"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '利用拡大に伴って (seiring meluasnya penggunaan) risiko serangan siber ikut meningkat.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan logistik berikut. Apa yang berubah?', '{"audio_text":"燃料費の高騰に伴い、来月より一部地域の配送料を改定させていただきます。","options":[{"id":"opt_1","text":"Jam operasional gudang diperpanjang hingga malam"},{"id":"opt_2","text":"Layanan pengiriman ke luar negeri dihentikan total"},{"id":"opt_3","text":"Biaya pengiriman di sebagian wilayah akan disesuaikan bulan depan"},{"id":"opt_4","text":"Semua pelanggan mendapatkan diskon pengiriman bulan depan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '配送料を改定する (menyesuaikan/merevisi tarif pengiriman) sering diumumkan dengan pola ～に伴い.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kutipan artikel berikut: 高齢化が進む___、医療や介護の費用も増大している。', '{"options":["に伴って","にあたって","わけにはいかない","に限らず"],"translation":"Seiring berlanjutnya penuaan penduduk, biaya medis dan perawatan lansia juga membengkak.","sentence_template":"高齢化が進む[blank]、医療や介護の費用も増大している。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, '高齢化が進む (proses perubahan) diikuti に伴って lalu 費用が増大している (perubahan paralel).', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 業務のデジタル化___コスト削減が、今年度の重要課題だ。', '{"options":["に伴う","に伴って","にあたり","にかかわらず"],"translation":"Pengurangan biaya yang menyertai digitalisasi operasional merupakan agenda penting tahun fiskal ini.","sentence_template":"業務のデジタル化[blank]コスト削減が、今年度の重要課題だ。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, 'Karena langsung memodifikasi kata benda コスト削減, bentuk yang benar adalah ～に伴う.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring perluasan pasar Asia, kebutuhan staf berbahasa asing meningkat."', '{"display_text":"アジア市場の拡大に伴い、語学力のある人材が求められています。","romaji":"Ajia shijou no kakudai ni tomonai, gogakuryoku no aru jinzai ga motomerarete imasu.","phonetic_breakdown":["あじあ","しじょうの","かくだいに","ともない","ごがくりょくのある","じんざいが","もとめられています"]}'::jsonb, '{"expected_transcript":"アジア市場の拡大に伴い、語学力のある人材が求められています。"}'::jsonb, '語学力のある人材 (SDM yang memiliki kemampuan bahasa) adalah frasa umum dalam rekrutmen global Jepang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seiring melemahnya yen, biaya barang impor menjadi naik."', '{"tokens":["進行した","円安の","進行","輸入品の","にあたって、","に伴って、","価格が","上がった。"],"target_translation":"Seiring melemahnya yen, biaya barang impor menjadi naik.","romaji":"Enyasu no shinkou ni tomonatte, yunyuuhin no kakaku ga agatta."}'::jsonb, '["円安の","進行","に伴って、","輸入品の","価格が","上がった。"]'::jsonb, '円安 (pelemahan yen) dan 輸入品 (barang impor) adalah kosakata kunci berita ekonomi Jepang.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seiring perubahan gaya hidup, kebutuhan makanan siap saji meningkat."', '{"tokens":["変化して","伸びている。","変化","に伴い、","冷凍食品の","にもかかわらず、","生活様式の","需要が"],"target_translation":"Seiring perubahan gaya hidup, kebutuhan makanan siap saji meningkat.","romaji":"Seikatsu youshiki no henka ni tomonai, reitou shokuhin no juyou ga nobite iru."}'::jsonb, '["生活様式の","変化","に伴い、","冷凍食品の","需要が","伸びている。"]'::jsonb, '需要が伸びる berarti permintaan pasar tumbuh atau meningkat.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Risiko yang menyertai investasi harus dijelaskan terlebih dahulu."', '{"tokens":["べきだ。","投資","事前に","にあたり","に伴う","説明する","に伴って","リスクは、"],"target_translation":"Risiko yang menyertai investasi harus dijelaskan terlebih dahulu.","romaji":"Toushi ni tomonau risuku wa, jizen ni setsumei suru beki da."}'::jsonb, '["投資","に伴う","リスクは、","事前に","説明する","べきだ。"]'::jsonb, '投資に伴うリスク berarti ''risiko yang menyertai investasi''.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring meluasnya belanja daring, beban kerja kurir pengiriman bertambah."', '{"display_text":"ネット通販の普及に伴って、配達員の負担が増えています。","romaji":"Netto tsuuhan no fukyuu ni tomonatte, haitatsuin no futan ga fuete imasu.","phonetic_breakdown":["ねっと","つうはんの","ふきゅうに","ともなって","はいたついんの","ふたんが","ふえています"]}'::jsonb, '{"expected_transcript":"ネット通販の普及に伴って、配達員の負担が増えています。"}'::jsonb, '負担が増える (beban bertambah) adalah kolokasi alami yang sering muncul di berita sosial.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring naiknya suhu bumi, cuaca ekstrem makin sering terjadi."', '{"display_text":"気温の上昇に伴い、異常気象が頻繁に発生しています。","romaji":"Kion no joushou ni tomonai, ijou kishou ga hinpan ni hassei shite imasu.","phonetic_breakdown":["きおんの","じょうしょうに","ともない","いじょうきしょうが","ひんぱんに","はっせいしています"]}'::jsonb, '{"expected_transcript":"気温の上昇に伴い、異常気象が頻繁に発生しています。"}'::jsonb, '異常気象 (cuaca ekstrem) dan 頻繁に (dengan sering) adalah kosakata penting bacaan N2.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring bertambahnya jumlah mahasiswa asing, layanan konseling diperkuat."', '{"display_text":"留学生の増加に伴って、相談窓口の体制が強化されました。","romaji":"Ryuugakusei no zouka ni tomonatte, soudan madoguchi no taisei ga kyouka saremashita.","phonetic_breakdown":["りゅうがくせいの","ぞうかに","ともなって","そうだんまどぐちの","たいせいが","きょうかされました"]}'::jsonb, '{"expected_transcript":"留学生の増加に伴って、相談窓口の体制が強化されました。"}'::jsonb, '相談窓口 (loket/layanan konsultasi) dan 体制が強化される (sistem diperkuat) sangat relevan dengan kehidupan kampus.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 自動運転技術が進化する___、法整備の見直しが求められている。', '{"options":["に伴って","にあたって","かねない","ざるを得ない"],"translation":"Seiring berkembangnya teknologi kemudi otonom, peninjauan ulang regulasi hukum semakin dituntut.","sentence_template":"自動運転技術が進化する[blank]、法整備の見直しが求められている。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, '進化する (berkembang) + に伴って menyatakan perubahan regulasi yang harus mengikuti perkembangan teknologi.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi frasa berikut: 組織再編___人事異動が、来週発表される予定だ。', '{"options":["に伴う","に伴って","に伴い","に限らず"],"translation":"Mutasi personalia yang menyertai reorganisasi dijadwalkan diumumkan minggu depan.","sentence_template":"組織再編[blank]人事異動が、来週発表される予定だ。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, '組織再編に伴う人事異動 menggunakan ～に伴う untuk memodifikasi kata benda 人事異動.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita lingkungan berikut. Apa yang meningkat seiring kesadaran lingkungan?', '{"audio_text":"環境意識の高まりに伴い、再生可能エネルギーへの投資が世界中で加速しています。","options":[{"id":"opt_1","text":"Investasi pada energi terbarukan di seluruh dunia"},{"id":"opt_2","text":"Produksi kendaraan berbahan bakar bensin"},{"id":"opt_3","text":"Impor batu bara untuk pembangkit listrik"},{"id":"opt_4","text":"Harga jual plastik sekali pakai"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '再生可能エネルギーへの投資 (investasi energi terbarukan) semakin cepat seiring meningkatnya kesadaran lingkungan.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman bank berikut. Mengapa jam layanan loket berubah?', '{"audio_text":"インターネットバンキングの利用増加に伴って、一部支店の窓口営業時間を短縮いたします。","options":[{"id":"opt_1","text":"Karena gedung cabang sedang direnovasi total"},{"id":"opt_2","text":"Karena staf bank sedang mengikuti pelatihan tahunan"},{"id":"opt_3","text":"Karena jumlah nasabah internet banking menurun"},{"id":"opt_4","text":"Karena penggunaan internet banking meningkat"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '利用増加に伴って berarti ''seiring meningkatnya penggunaan''.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seiring pertumbuhan kota, jaringan kereta bawah tanah diperluas."', '{"tokens":["に伴って、","路線網が","都市の","地下鉄の","広がった。","にあたって、","発展","発展して"],"target_translation":"Seiring pertumbuhan kota, jaringan kereta bawah tanah diperluas.","romaji":"Toshi no hatten ni tomonatte, chikatetsu no rosenmou ga hirogatta."}'::jsonb, '["都市の","発展","に伴って、","地下鉄の","路線網が","広がった。"]'::jsonb, '路線網 (rosenmou) berarti jaringan jalur transportasi.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring globalisasi bisnis, pemahaman lintas budaya menjadi makin penting."', '{"display_text":"ビジネスの国際化に伴い、異文化理解の重要性が増しています。","romaji":"Bijinesu no kokusaika ni tomonai, ibunka rikai no juuyousei ga mashite imasu.","phonetic_breakdown":["びじねすの","こくさいかに","ともない","いぶんかりかいの","じゅうようせいが","ましています"]}'::jsonb, '{"expected_transcript":"ビジネスの国際化に伴い、異文化理解の重要性が増しています。"}'::jsonb, '重要性が増す (tingkat kepentingan meningkat) adalah ungkapan akademis & bisnis tingkat N2.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: このアプリは若者だけでなく、幅広い___から支持されている。', '{"options":["世代","気候","納期","予算"],"translation":"Aplikasi ini didukung bukan hanya oleh anak muda, melainkan oleh berbagai generasi secara luas.","sentence_template":"このアプリは若者だけでなく、幅広い[blank]から支持されている。"}'::jsonb, '{"selected":"世代"}'::jsonb, '世代 (sedai) berarti generasi atau kelompok usia.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat pemasaran berikut: 当社の製品は国内だけでなく、海外の___からも高い評価を得ている。', '{"options":["顧客","欠席","延期","渋滞"],"translation":"Produk perusahaan kami memperoleh penilaian tinggi bukan hanya di dalam negeri, melainkan juga dari pelanggan luar negeri.","sentence_template":"当社の製品は国内だけでなく、海外の[blank]からも高い評価を得ている。"}'::jsonb, '{"selected":"顧客"}'::jsonb, '顧客 (kokyaku) adalah istilah formal untuk pelanggan atau klien bisnis.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 現代の企業には、人材の___を尊重する姿勢が求められる。', '{"options":["多様性","少子化","物価高","転勤"],"translation":"Perusahaan modern dituntut memiliki sikap yang menghargai keragaman sumber daya manusia.","sentence_template":"現代の企業には、人材の[blank]を尊重する姿勢が求められる。"}'::jsonb, '{"selected":"多様性"}'::jsonb, '多様性 (tayousei) berarti keberagaman atau diversitas.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan deskripsi produk berikut. Siapa saja yang menggunakan layanan ini?', '{"audio_text":"このオンライン講座は学生に限らず、社会人の学び直しにも広く活用されています。","options":[{"id":"opt_1","text":"Hanya mahasiswa tingkat pertama"},{"id":"opt_2","text":"Mahasiswa maupun pekerja profesional yang belajar kembali"},{"id":"opt_3","text":"Khusus dosen dan peneliti universitas"},{"id":"opt_4","text":"Hanya siswa sekolah menengah atas"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '学生に限らず (tidak terbatas pada mahasiswa) + 社会人 (pekerja/masyarakat umum) menunjukkan cakupan luas.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan wawancara berikut. Di mana merek tersebut populer?', '{"audio_text":"日本のアニメ文化はアジアに限らず、ヨーロッパや北米でも熱心なファンが多い。","options":[{"id":"opt_1","text":"Hanya di kawasan Asia Timur"},{"id":"opt_2","text":"Khusus di kota-kota besar Jepang"},{"id":"opt_3","text":"Di Asia, Eropa, hingga Amerika Utara"},{"id":"opt_4","text":"Hanya di negara-negara berbahasa Inggris"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'アジアに限らず berarti tidak terbatas di Asia, melainkan meluas ke Eropa dan Amerika Utara.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Layanan ini tersedia bukan hanya di dalam negeri, tetapi juga di seluruh dunia."', '{"display_text":"このサービスは国内に限らず、世界中で利用できます。","romaji":"Kono saabisu wa kokunai ni kagirazu, sekaijuu de riyou dekimasu.","phonetic_breakdown":["このさーびすは","こくないに","かぎらず","せかいじゅうで","りようできます"]}'::jsonb, '{"expected_transcript":"このサービスは国内に限らず、世界中で利用できます。"}'::jsonb, '国内に限らず (tidak terbatas di dalam negeri) sering dipasangkan dengan 世界中で (di seluruh dunia).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pola N2 berikut: 語学の習得は英語___、毎日の継続的な練習が大切だ。', '{"options":["に限らず","にあたって","に伴って","かねない"],"translation":"Penguasaan bahasa tidak terbatas pada bahasa Inggris, latihan rutin setiap hari sangat penting.","sentence_template":"語学の習得は英語[blank]、毎日の継続的な練習が大切だ。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, 'Kata Benda + に限らず berarti ''tidak hanya terbatas pada [Kata Benda], tetapi juga berlaku untuk yang lain''.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: このスポーツクラブは会員___、一般の方も体験利用が可能だ。', '{"options":["に限らず","ざるを得ず","にもかかわらず","つつあり"],"translation":"Klub olahraga ini tidak terbatas bagi anggota saja; masyarakat umum pun dapat mencoba layanan uji coba.","sentence_template":"このスポーツクラブは会員[blank]、一般の方も体験利用が可能だ。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '会員に限らず (tidak terbatas pada anggota) sangat lazim dalam pengumuman fasilitas umum.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi berikut: ___に限らず、どの仕事でも基礎を固めることが成功の鍵となる。', '{"options":["IT分野","IT分野を","IT分野で","IT分野に"],"translation":"Tidak terbatas pada bidang IT, dalam pekerjaan apa pun memperkuat dasar adalah kunci keberhasilan.","sentence_template":"[blank]に限らず、どの仕事でも基礎を固めることが成功の鍵となる。"}'::jsonb, '{"selected":"IT分野"}'::jsonb, 'Di depan に限らず, kata benda dipakai langsung tanpa partikel tambahan.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Masalah ini tidak terbatas di Jepang, tetapi juga terjadi di banyak negara."', '{"tokens":["国で","起きている。","に限らず、","にあたって、","日本に","この問題は","日本","多くの"],"target_translation":"Masalah ini tidak terbatas di Jepang, tetapi juga terjadi di banyak negara.","romaji":"Kono mondai wa Nihon ni kagirazu, ooku no kuni de okite iru."}'::jsonb, '["この問題は","日本","に限らず、","多くの","国で","起きている。"]'::jsonb, '日本に限らず (tidak terbatas pada Jepang) diikuti pernyataan yang memperluas cakupan ke banyak negara.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seminar ini dapat diikuti tidak terbatas pada usia maupun kewarganegaraan."', '{"tokens":["参加できる。","このセミナーは","に限らず、","国籍","年齢や","誰でも","国籍を","に伴って、"],"target_translation":"Seminar ini dapat diikuti tidak terbatas pada usia maupun kewarganegaraan.","romaji":"Kono seminaa wa nenrei ya kokuseki ni kagirazu, daredemo sanka dekiru."}'::jsonb, '["このセミナーは","年齢や","国籍","に限らず、","誰でも","参加できる。"]'::jsonb, 'Kombinasi AやBに限らず menegaskan bahwa tidak ada batasan pada kedua kategori tersebut.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Produk ramah lingkungan tidak terbatas pada makanan, tetapi juga meluas ke pakaian."', '{"display_text":"環境に優しい製品は食品に限らず、衣類にも広がっています。","romaji":"Kankyou ni yasashii seihin wa shokuhin ni kagirazu, irui ni mo hirogatte imasu.","phonetic_breakdown":["かんきょうに","やさしい","せいひんは","しょくひんに","かぎらず","いるいにも","ひろがっています"]}'::jsonb, '{"expected_transcript":"環境に優しい製品は食品に限らず、衣類にも広がっています。"}'::jsonb, '衣類 (irui) berarti pakaian/sandang; 広がる berarti meluas.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan iklan fasilitas berikut. Kapan kafe tersebut ramai pengunjung?', '{"audio_text":"駅前の新しいカフェは平日に限らず、週末もビジネス客や学生で賑わっている。","options":[{"id":"opt_1","text":"Hanya pada hari kerja saat jam makan siang"},{"id":"opt_2","text":"Baik pada hari kerja maupun akhir pekan"},{"id":"opt_3","text":"Hanya pada malam hari menjelang tutup"},{"id":"opt_4","text":"Khusus saat hari libur nasional saja"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '平日に限らず、週末も berarti tidak terbatas pada hari kerja, akhir pekan pun ramai.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan kepala HRD berikut. Apa kebijakan perekrutan perusahaan itu?', '{"audio_text":"当社では新卒に限らず、異業種からの転職者も積極的に採用しています。","options":[{"id":"opt_1","text":"Hanya menerima lulusan baru dari universitas negeri"},{"id":"opt_2","text":"Menghentikan perekrutan karyawan baru tahun ini"},{"id":"opt_3","text":"Membuka peluang bagi lulusan baru maupun pelamar lintas industri"},{"id":"opt_4","text":"Hanya menerima pelamar dengan pengalaman di industri yang sama"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '新卒に限らず (tidak terbatas lulusan baru) dan 異業種からの転職者 (pelamar pindah karier dari industri berbeda).', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan berita pariwisata berikut. Mengapa kota ini populer sepanjang tahun?', '{"audio_text":"この観光地は桜の季節に限らず、秋の紅葉や冬の雪景色も魅力的だからです。","options":[{"id":"opt_1","text":"Karena biaya hotel di sana selalu sangat murah"},{"id":"opt_2","text":"Karena mudah dijangkau dengan pesawat langsung"},{"id":"opt_3","text":"Karena terkenal dengan pusat perbelanjaan modernnya"},{"id":"opt_4","text":"Karena menawarkan keindahan di berbagai musim, bukan hanya musim sakura"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '桜の季節に限らず menegaskan daya tarik tidak terbatas pada musim semi saja.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi bacaan bisnis berikut: 最近の消費者は価格___、企業の環境への取り組みも重視している。', '{"options":["に限らず","にあたって","わけにはいかず","ざるを得ず"],"translation":"Konsumen masa kini tidak hanya memperhatikan harga, tetapi juga mementingkan upaya lingkungan perusahaan.","sentence_template":"最近の消費者は価格[blank]、企業の環境への取り組みも重視している。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '価格に限らず menunjukkan bahwa faktor penilaian konsumen meluas di luar harga semata.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih partikel pelengkap yang alami: この図書館は本に限らず、電子資料や雑誌___利用できる。', '{"options":["も","だけ","しか","より"],"translation":"Perpustakaan ini tidak terbatas pada buku saja, melainkan juga menyediakan materi elektronik dan majalah.","sentence_template":"この図書館は本に限らず、電子資料や雑誌[blank]利用できる。"}'::jsonb, '{"selected":"も"}'::jsonb, 'Pola ～に限らず sangat sering berpasangan dengan partikel も di klausa berikutnya.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di restoran ini, bukan hanya masakan Jepang, masakan Asia juga populer."', '{"display_text":"このレストランでは和食に限らず、アジア料理も人気があります。","romaji":"Kono resutoran de wa washoku ni kagirazu, Ajia ryouri mo ninki ga arimasu.","phonetic_breakdown":["このれすとらんでは","わしょくに","かぎらず","あじありょうりも","にんきがあります"]}'::jsonb, '{"expected_transcript":"このレストランでは和食に限らず、アジア料理も人気があります。"}'::jsonb, '和食 (washoku) berarti masakan Jepang; dipasangkan dengan も pada klausa kedua.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bukan hanya di kota besar, di daerah pun acara ini diselenggarakan."', '{"tokens":["開催","地方でも","大都市に","されている。","に伴って、","大都市","に限らず、","このイベントは"],"target_translation":"Bukan hanya di kota besar, di daerah pun acara ini diselenggarakan.","romaji":"Daitoshi ni kagirazu, chihou demo kono ibento wa kaisai sarete iru."}'::jsonb, '["大都市","に限らず、","地方でも","このイベントは","開催","されている。"]'::jsonb, '大都市に限らず、地方でも kontras antara kota besar dan daerah untuk menunjukkan cakupan nasional.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tidak terbatas pada bidang medis, AI digunakan di berbagai industri."', '{"tokens":["にあたって、","あらゆる","活用されている。","に限らず、","産業で","AIは","医療分野を","医療分野"],"target_translation":"Tidak terbatas pada bidang medis, AI digunakan di berbagai industri.","romaji":"Iryou bunya ni kagirazu, eiai wa arayuru sangyou de katsuyou sarete iru."}'::jsonb, '["医療分野","に限らず、","AIは","あらゆる","産業で","活用されている。"]'::jsonb, 'あらゆる (segala/berbagai) sangat cocok menguatkan makna inklusif dari ～に限らず.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Keterampilan komunikasi penting tidak terbatas pada pekerjaan penjualan."', '{"tokens":["すべての","に限らず、","にもかかわらず、","営業職","コミュニケーション力は","営業職の","重要だ。","職種で"],"target_translation":"Keterampilan komunikasi penting tidak terbatas pada pekerjaan penjualan.","romaji":"Komyunikeeshon-ryoku wa eigyoushoku ni kagirazu, subete no shokushu de juuyou da."}'::jsonb, '["コミュニケーション力は","営業職","に限らず、","すべての","職種で","重要だ。"]'::jsonb, '営業職 (posisi penjualan) dan 職種 (jenis pekerjaan/jabatan) adalah kosakata karier N2.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak terbatas pada pria, wanita juga banyak berkarya di bidang teknik."', '{"display_text":"男性に限らず、女性も技術分野で広く活躍しています。","romaji":"Dansei ni kagirazu, josei mo gijutsu bunya de hiroku katsuyaku shite imasu.","phonetic_breakdown":["だんせいに","かぎらず","じょせいも","ぎじゅつぶんやで","ひろく","かつやくしています"]}'::jsonb, '{"expected_transcript":"男性に限らず、女性も技術分野で広く活躍しています。"}'::jsonb, '活躍する (katsuyaku suru) berarti berperan aktif atau berkarya secara gemilang.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak terbatas pada musim panas, menjaga asupan cairan itu penting sepanjang tahun."', '{"display_text":"夏に限らず、一年中こまめな水分補給が大切です。","romaji":"Natsu ni kagirazu, ichinenjuu komamena suibun hokyuu ga taisetsu desu.","phonetic_breakdown":["なつに","かぎらず","いちねんじゅう","こまめな","すいぶんほきゅうが","たいせつです"]}'::jsonb, '{"expected_transcript":"夏に限らず、一年中こまめな水分補給が大切です。"}'::jsonb, '水分補給 (asupan cairan) dan こまめな (rutin/sedikit demi sedikit) sering muncul di pengumuman kesehatan.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak terbatas pada buku teks, saya belajar bahasa Jepang lewat berita juga."', '{"display_text":"教科書に限らず、ニュース記事からも日本語を学んでいます。","romaji":"Kyoukasho ni kagirazu, nyuusu kiji kara mo Nihongo o manande imasu.","phonetic_breakdown":["きょうかしょに","かぎらず","にゅーすきじからも","にほんごを","まなんでいます"]}'::jsonb, '{"expected_transcript":"教科書に限らず、ニュース記事からも日本語を学んでいます。"}'::jsonb, 'Kalimat ini alami untuk wawancara kerja atau wawancara beasiswa di Jepang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang paling sesuai: このデザインは専門家___、一般の利用者からも高く評価された。', '{"options":["に限らず","に伴って","にあたって","かねない"],"translation":"Desain ini mendapat penilaian tinggi tidak hanya dari para ahli, melainkan juga dari pengguna umum.","sentence_template":"このデザインは専門家[blank]、一般の利用者からも高く評価された。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '専門家に限らず memperluas subjek pemberi evaluasi hingga ke pengguna umum.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 災害対策は地震___、台風や豪雨への備えも欠かせない。', '{"options":["に限らず","わけにはいかず","ざるを得ず","つつあり"],"translation":"Mitigasi bencana tidak terbatas pada gempa bumi, persiapan menghadapi topan dan hujan lebat juga tak boleh dilewatkan.","sentence_template":"災害対策は地震[blank]、台風や豪雨への備えも欠かせない。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '災害対策 (mitigasi bencana) dan 備え (persiapan) adalah kosakata penting tinggal di Jepang.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan presentasi produk berikut. Mengapa desain aplikasi ini dipuji?', '{"audio_text":"文字の大きさや色使いを工夫した結果、高齢者に限らず誰にとっても使いやすいアプリになりました。","options":[{"id":"opt_1","text":"Karena mudah digunakan semua orang, bukan hanya lansia"},{"id":"opt_2","text":"Karena hanya dapat diunduh secara gratis oleh lansia"},{"id":"opt_3","text":"Karena memiliki fitur permainan berbayar di dalamnya"},{"id":"opt_4","text":"Karena hanya memakai warna hitam dan putih"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '高齢者に限らず誰にとっても使いやすい berarti mudah digunakan siapa saja, tidak terbatas pada lansia.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar dosen berikut. Apa pesan utamanya kepada mahasiswa?', '{"audio_text":"自分の専門分野に限らず、幅広い知識を身につけることが将来の研究に役立ちます。","options":[{"id":"opt_1","text":"Fokus hanya pada satu buku wajib di semester ini"},{"id":"opt_2","text":"Kurangi jumlah mata kuliah pilihan di luar jurusan"},{"id":"opt_3","text":"Kuasai pengetahuan luas, tidak terbatas pada bidang spesialisasi sendiri"},{"id":"opt_4","text":"Segera tentukan topik skripsi sebelum kuliah dimulai"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '専門分野に限らず (tidak terbatas pada bidang spesialisasi) + 幅広い知識 (pengetahuan luas).', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tidak terbatas pada kopi, kafe ini menyediakan berbagai teh herbal."', '{"tokens":["ハーブティーも","コーヒーを","揃えている。","このカフェは","にあたって、","様々な","に限らず、","コーヒー"],"target_translation":"Tidak terbatas pada kopi, kafe ini menyediakan berbagai teh herbal.","romaji":"Kono kafe wa koohii ni kagirazu, samazamana haabutii mo soroete iru."}'::jsonb, '["このカフェは","コーヒー","に限らず、","様々な","ハーブティーも","揃えている。"]'::jsonb, '揃えている (menyediakan secara lengkap) sering dipakai untuk menu atau koleksi barang.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak terbatas pada perusahaan besar, perusahaan rintisan pun mulai merekrut secara global."', '{"display_text":"大企業に限らず、ベンチャー企業でもグローバル採用が進んでいます。","romaji":"Daikigyou ni kagirazu, benchaa kigyou demo guroobaru saiyou ga susunde imasu.","phonetic_breakdown":["だいきぎょうに","かぎらず","べんちゃー","きぎょうでも","ぐろーばるさいようが","すすんでいます"]}'::jsonb, '{"expected_transcript":"大企業に限らず、ベンチャー企業でもグローバル採用が進んでいます。"}'::jsonb, 'ベンチャー企業 (perusahaan rintisan/startup) dan グローバル採用 (rekrutmen global) populer di dunia karier Jepang.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 会社の___情報を外部に漏らすことは厳禁されている。', '{"options":["機密","観光","趣味","天気"],"translation":"Membocorkan informasi rahasia perusahaan ke pihak luar sangat dilarang keras.","sentence_template":"会社の[blank]情報を外部に漏らすことは厳禁されている。"}'::jsonb, '{"selected":"機密"}'::jsonb, '機密情報 (kimitsu jouhou) berarti informasi rahasia/konfidensial perusahaan.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kerja berikut: 顧客との約束である___を守るため、チーム全員で協力した。', '{"options":["納期","気温","世代","景色"],"translation":"Demi menepati tenggat pengiriman yang telah dijanjikan kepada klien, seluruh tim bekerja sama.","sentence_template":"顧客との約束である[blank]を守るため、チーム全員で協力した。"}'::jsonb, '{"selected":"納期"}'::jsonb, '納期 (nouki) berarti tenggat waktu penyerahan atau pengiriman proyek/produk.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: プロジェクトの責任者という___上、簡単に諦めることはできない。', '{"options":["立場","物価","普及","季節"],"translation":"Dilihat dari posisi saya sebagai penanggung jawab proyek, saya tidak bisa menyerah begitu saja.","sentence_template":"プロジェクトの責任者という[blank]上、簡単に諦めることはできない。"}'::jsonb, '{"selected":"立場"}'::jsonb, '立場 (tachiba) berarti posisi, kedudukan, atau peran seseorang dalam organisasi.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja berikut. Mengapa pembicara tidak bisa pulang lebih awal?', '{"audio_text":"明日のプレゼンの最終確認が終わっていないので、このまま帰るわけにはいかないんだ。","options":[{"id":"opt_1","text":"Karena pemeriksaan akhir presentasi besok belum selesai"},{"id":"opt_2","text":"Karena kereta terakhir sudah berangkat"},{"id":"opt_3","text":"Karena sedang menunggu paket pribadi di kantor"},{"id":"opt_4","text":"Karena hujan deras di luar gedung"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '最終確認が終わっていない (pengecekan akhir belum selesai) membuat pembicara merasa tidak pantas pulang.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan berikut. Apa yang dijaga oleh pembicara?', '{"audio_text":"せっかく築いた取引先との信頼を失うわけにはいきません。","options":[{"id":"opt_1","text":"Jadwal cuti musim panas tim penjualan"},{"id":"opt_2","text":"Kepercayaan mitra bisnis yang sudah susah payah dibangun"},{"id":"opt_3","text":"Anggaran makan siang bulanan kantor"},{"id":"opt_4","text":"Koleksi buku panduan di ruang rapat"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '信頼を失う (kehilangan kepercayaan) adalah hal yang tidak boleh terjadi secara profesional.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena sudah berjanji, saya tidak mungkin melanggarnya."', '{"display_text":"一度約束した以上、破るわけにはいきません。","romaji":"Ichido yakusoku shita ijou, yaburu wake ni wa ikimasen.","phonetic_breakdown":["いちど","やくそくした","いじょう","やぶる","わけには","いきません"]}'::jsonb, '{"expected_transcript":"一度約束した以上、破るわけにはいきません。"}'::jsonb, '約束を破る berarti melanggar janji; dipadukan dengan ～わけにはいきません untuk menegaskan komitmen.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 重要な会議の司会を任されたので、風邪気味でも___わけにはいかない。', '{"options":["休む","休んだ","休んで","休み"],"translation":"Karena dipercaya menjadi moderator rapat penting, meski agak masuk angin saya tidak bisa libur.","sentence_template":"重要な会議の司会を任されたので、風邪気味でも[blank]わけにはいかない。"}'::jsonb, '{"selected":"休む"}'::jsonb, 'Sebelum わけにはいかない, verba menggunakan bentuk kamus (休む) atau bentuk ない.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk negatif ganda yang tepat (''mau tidak mau harus''): 上司から直接頼まれた仕事なので、___わけにはいかない。', '{"options":["引き受けない","引き受ける","引き受けた","引き受けて"],"translation":"Karena pekerjaan ini diminta langsung oleh atasan, mau tidak mau saya harus menerimanya.","sentence_template":"上司から直接頼まれた仕事なので、[blank]わけにはいかない。"}'::jsonb, '{"selected":"引き受けない"}'::jsonb, 'V-ない + わけにはいかない berarti ''tidak bisa tidak melakukan'' alias mau tidak mau harus melakukan.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pola N2 berikut: ここは病院の待合室なので、大声で話す___。', '{"options":["わけにはいかない","にあたって","に伴って","に限らず"],"translation":"Karena ini ruang tunggu rumah sakit, tidak pantas berbicara dengan suara keras.","sentence_template":"ここは病院の待合室なので、大声で話す[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, '～わけにはいかない menyatakan ketidakbolehan berdasarkan norma sosial atau kepantasan.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Saya tidak mungkin menceritakan rahasia teman kepada orang lain."', '{"tokens":["わけには","話した","話す","友人の","秘密を","いかない。","他人に","に限らず"],"target_translation":"Saya tidak mungkin menceritakan rahasia teman kepada orang lain.","romaji":"Yuujin no himitsu o tanin ni hanasu wake ni wa ikanai."}'::jsonb, '["友人の","秘密を","他人に","話す","わけには","いかない。"]'::jsonb, 'Urutan baku: [Objek] + [V-dict] + わけにはいかない.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah diundang ke pernikahan atasan, mau tidak mau saya harus hadir."', '{"tokens":["招待されたので、","上司の","出席する","わけには","結婚式に","出席しない","いかない。","かねない。"],"target_translation":"Karena sudah diundang ke pernikahan atasan, mau tidak mau saya harus hadir.","romaji":"Joushi no kekkonshiki ni shoutai sareta node, shusseki shinai wake ni wa ikanai."}'::jsonb, '["上司の","結婚式に","招待されたので、","出席しない","わけには","いかない。"]'::jsonb, '出席しないわけにはいかない (tidak bisa tidak hadir = harus hadir karena etika sosial).', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya tidak mungkin berhenti di tengah jalan pada proyek ini."', '{"display_text":"このプロジェクトを途中で諦めるわけにはいきません。","romaji":"Kono purojekuto o tochuu de akirameru wake ni wa ikimasen.","phonetic_breakdown":["このぷろじぇくとを","とちゅうで","あきらめる","わけには","いきません"]}'::jsonb, '{"expected_transcript":"このプロジェクトを途中で諦めるわけにはいきません。"}'::jsonb, '途中で諦める berarti menyerah di tengah jalan.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan di kantor berikut. Mengapa pembicara menolak tawaran minum?', '{"audio_text":"今夜はこれから車で家族を迎えに行くので、お酒を飲むわけにはいかないんです。","options":[{"id":"opt_1","text":"Karena sedang diet ketat menjelang pemeriksaan kesehatan"},{"id":"opt_2","text":"Karena tidak menyukai rasa minuman tersebut"},{"id":"opt_3","text":"Karena akan menyetir mobil untuk menjemput keluarga"},{"id":"opt_4","text":"Karena harus langsung masuk kerja shift malam"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '車で家族を迎えに行く (menjemput keluarga dengan mobil) membuat minum alkohol melanggar hukum & keselamatan.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan ucapan mahasiswa berikut. Apa yang akan ia lakukan?', '{"audio_text":"明日は奨学金の面接があるから、今夜は夜更かしするわけにはいかない。","options":[{"id":"opt_1","text":"Begadang semalaman untuk menonton film"},{"id":"opt_2","text":"Tidur lebih awal dan tidak begadang karena ada wawancara beasiswa besok"},{"id":"opt_3","text":"Mengubah jadwal wawancara ke minggu depan"},{"id":"opt_4","text":"Pergi makan malam bersama teman sampai larut"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '夜更かしするわけにはいかない berarti ''tidak boleh begadang'' karena ada agenda penting esok hari.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan kepala tim berikut. Apa alasannya tidak bisa menunda pengiriman?', '{"audio_text":"すでに工場の稼働スケジュールが決まっているので、部品の納入を遅らせるわけにはいきません。","options":[{"id":"opt_1","text":"Karena harga komponen akan naik minggu depan"},{"id":"opt_2","text":"Karena gudang penyimpanan sudah penuh"},{"id":"opt_3","text":"Karena truk pengiriman sedang diperbaiki"},{"id":"opt_4","text":"Karena jadwal operasional pabrik sudah ditetapkan"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '工場の稼働スケジュールが決まっている (jadwal operasional pabrik sudah tetap) sehingga pengiriman komponen tak bisa ditunda.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 試験の本番まであと一週間だから、ここで気を緩める___。', '{"options":["わけにはいかない","にあたって","に伴う","つつある"],"translation":"Karena ujian sesungguhnya tinggal satu minggu lagi, saya tidak boleh lengah di saat seperti ini.","sentence_template":"試験の本番まであと一週間だから、ここで気を緩める[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, '気を緩める (melengahkan diri/mengendurkan fokus) + わけにはいかない.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 顧客からクレームが入った以上、誠意を持って___わけにはいかない。', '{"options":["対応しない","対応する","対応した","対応して"],"translation":"Begitu ada keluhan dari pelanggan, mau tidak mau kami harus menanganinya dengan sungguh-sungguh.","sentence_template":"顧客からクレームが入った以上、誠意を持って[blank]わけにはいかない。"}'::jsonb, '{"selected":"対応しない"}'::jsonb, '誠意を持って対応しないわけにはいかない menegaskan kewajiban profesional menanggapi keluhan.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena rekan kerja sedang kesulitan, saya tidak mungkin diam saja melihatnya."', '{"display_text":"同僚が困っているのに、黙って見ているわけにはいきません。","romaji":"Douryou ga komatte iru noni, damatte mite iru wake ni wa ikimasen.","phonetic_breakdown":["どうりょうが","こまっているのに","だまって","みている","わけには","いきません"]}'::jsonb, '{"expected_transcript":"同僚が困っているのに、黙って見ているわけにはいきません。"}'::jsonb, '黙って見ているわけにはいかない berarti tidak bisa hanya diam menonton tanpa membantu.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena ini data sebelum rilis, saya tidak boleh menunjukkannya ke pihak luar."', '{"tokens":["データなので、","見せる","いかない。","わけには","にあたって","公開前の","社外に","見せない"],"target_translation":"Karena ini data sebelum rilis, saya tidak boleh menunjukkannya ke pihak luar.","romaji":"Koukai mae no deeta nanode, shagai ni miseru wake ni wa ikanai."}'::jsonb, '["公開前の","データなので、","社外に","見せる","わけには","いかない。"]'::jsonb, '社外 (pihak luar perusahaan) vs 社内 (internal perusahaan).', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena orang tua mendukung studi saya, saya tidak boleh malas belajar."', '{"tokens":["わけには","応援してくれているので、","両親が","怠けない","留学を","怠ける","に伴って","いかない。"],"target_translation":"Karena orang tua mendukung studi saya, saya tidak boleh malas belajar.","romaji":"Ryoushin ga ryuugaku o ouen shite kurete iru node, namakeru wake ni wa ikanai."}'::jsonb, '["両親が","留学を","応援してくれているので、","怠ける","わけには","いかない。"]'::jsonb, '怠ける (namakeru) berarti bermalas-malasan.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena telah membuat kesalahan, mau tidak mau saya harus segera meminta maaf."', '{"tokens":["謝らない","ミスを","に限らず","謝る","わけには","すぐに","いかない。","してしまったので、"],"target_translation":"Karena telah membuat kesalahan, mau tidak mau saya harus segera meminta maaf.","romaji":"Misu o shite shimatta node, sugu ni ayamaranai wake ni wa ikanai."}'::jsonb, '["ミスを","してしまったので、","すぐに","謝らない","わけには","いかない。"]'::jsonb, '謝らないわけにはいかない (tidak bisa tidak meminta maaf = wajib meminta maaf).', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya tidak mungkin menolak permintaan penting dari klien lama."', '{"display_text":"長年のお取引先からの大切なご依頼を断るわけにはいきません。","romaji":"Naganen no otorihikisaki kara no taisetsuna goirai o kotowaru wake ni wa ikimasen.","phonetic_breakdown":["ながねんの","おとりひきさきからの","たいせつな","ごいらいを","ことわる","わけには","いきません"]}'::jsonb, '{"expected_transcript":"長年のお取引先からの大切なご依頼を断るわけにはいきません。"}'::jsonb, 'ご依頼を断る berarti menolak permintaan/pesanan dari klien.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun sangat lelah, saya tidak bisa membiarkan laporan ini belum selesai."', '{"display_text":"いくら疲れていても、この報告書を放っておくわけにはいきません。","romaji":"Ikura tsukarete ite mo, kono houkokusho o houtte oku wake ni wa ikimasen.","phonetic_breakdown":["いくら","つかれていても","このほうこくしょを","ほうっておく","わけには","いきません"]}'::jsonb, '{"expected_transcript":"いくら疲れていても、この報告書を放っておくわけにはいきません。"}'::jsonb, '放っておく (houtte oku) berarti membiarkan begitu saja tanpa diurus.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena sudah dipilih sebagai perwakilan tim, saya harus memberikan yang terbaik."', '{"display_text":"チームの代表に選ばれたからには、全力を尽くさないわけにはいきません。","romaji":"Chiimu no daihyou ni erabareta kara ni wa, zenryoku o tsukusanai wake ni wa ikimasen.","phonetic_breakdown":["ちーむの","だいひょうに","えらばれたからには","ぜんりょくを","つくさない","わけにはいきません"]}'::jsonb, '{"expected_transcript":"チームの代表に選ばれたからには、全力を尽くさないわけにはいきません。"}'::jsonb, '全力を尽くす (mengerahkan segenap tenaga) + ないわけにはいきません.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 会社の看板を背負っている以上、いい加減な仕事をする___。', '{"options":["わけにはいかない","にあたって","に伴って","に限らず"],"translation":"Selama membawa nama baik perusahaan, saya tidak boleh bekerja secara asal-asalan.","sentence_template":"会社の看板を背負っている以上、いい加減な仕事をする[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, 'いい加減な仕事 (pekerjaan asal-asalan) + わけにはいかない menyatakan standar etika kerja.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: せっかく先輩が丁寧に教えてくれたのだから、感謝___わけにはいかない。', '{"options":["しない","する","した","して"],"translation":"Karena senior sudah bersusah payah mengajari dengan sabar, mau tidak mau saya harus berterima kasih.","sentence_template":"せっかく先輩が丁寧に教えてくれたのだから、感謝[blank]わけにはいかない。"}'::jsonb, '{"selected":"しない"}'::jsonb, '感謝しないわけにはいかない (tidak pantas jika tidak berterima kasih).', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan berikut. Mengapa pembicara tetap datang ke rapat meski kurang sehat?', '{"audio_text":"今日の会議は私が主導する予定なので、少し熱があっても欠席するわけにはいかないんです。","options":[{"id":"opt_1","text":"Karena dialah yang dijadwalkan memimpin rapat hari ini"},{"id":"opt_2","text":"Karena rapat tersebut menyediakan makan siang gratis"},{"id":"opt_3","text":"Karena ruang rapat terletak di sebelah klinik"},{"id":"opt_4","text":"Karena dia lupa membawa laptop pulang kemarin"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '私が主導する予定 (saya yang dijadwalkan memimpin) menjadi alasan tanggung jawabnya.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pernyataan berikut. Apa sikap pembicara terhadap informasi tersebut?', '{"audio_text":"正式な発表があるまでは、この計画について他部署の人にも話すわけにはいきません。","options":[{"id":"opt_1","text":"Akan segera menyebarkannya melalui grup obrolan"},{"id":"opt_2","text":"Akan mencetaknya untuk ditempel di papan pengumuman"},{"id":"opt_3","text":"Tidak akan membicarakannya bahkan ke departemen lain sebelum pengumuman resmi"},{"id":"opt_4","text":"Sudah mendiskusikannya dengan semua karyawan kemarin"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '他部署の人にも話すわけにはいかない menegaskan kewajiban menjaga kerahasiaan internal.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena batas waktu pengumpulan adalah hari ini, saya tidak bisa menundanya."', '{"tokens":["わけには","先延ばしに","提出期限が","しない","にもかかわらず","する","いかない。","今日なので、"],"target_translation":"Karena batas waktu pengumpulan adalah hari ini, saya tidak bisa menundanya.","romaji":"Teishutsu kigen ga kyou nanode, sakinobashi ni suru wake ni wa ikanai."}'::jsonb, '["提出期限が","今日なので、","先延ばしに","する","わけには","いかない。"]'::jsonb, '先延ばしにする berarti menunda-nunda pekerjaan.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Demi keselamatan pelanggan, kami tidak boleh mengabaikan kelainan sekecil apa pun."', '{"display_text":"お客様の安全のため、小さな異常も見過ごすわけにはいきません。","romaji":"Okyakusama no anzen no tame, chiisana ijou mo misugosu wake ni wa ikimasen.","phonetic_breakdown":["おきゃくさまの","あんぜんのため","ちいさな","いじょうも","みすごす","わけにはいきません"]}'::jsonb, '{"expected_transcript":"お客様の安全のため、小さな異常も見過ごすわけにはいきません。"}'::jsonb, '見過ごす (misugosu) berarti melewatkan atau mengabaikan sesuatu yang penting.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 台風の接近により、屋外イベントは___になった。', '{"options":["中止","開会","普及","歓迎"],"translation":"Akibat mendekatnya topan, acara luar ruangan dibatalkan.","sentence_template":"台風の接近により、屋外イベントは[blank]になった。"}'::jsonb, '{"selected":"中止"}'::jsonb, '中止 (chuushi) berarti pembatalan suatu kegiatan atau proyek.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 業績の悪化を受け、海外市場からの___を検討している。', '{"options":["撤退","設立","採用","進学"],"translation":"Menyikapi memburuknya kinerja bisnis, kami mempertimbangkan penarikan diri dari pasar luar negeri.","sentence_template":"業績の悪化を受け、海外市場からの[blank]を検討している。"}'::jsonb, '{"selected":"撤退"}'::jsonb, '撤退 (tettai) berarti penarikan diri dari pasar, proyek, atau wilayah usaha.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 限られた___の中で、最も効果的な対策を選ぶ必要がある。', '{"options":["予算","挨拶","世代","気候"],"translation":"Di dalam anggaran yang terbatas, kita perlu memilih langkah penanggulangan yang paling efektif.","sentence_template":"限られた[blank]の中で、最も効果的な対策を選ぶ必要がある。"}'::jsonb, '{"selected":"予算"}'::jsonb, '予算 (yosan) berarti anggaran biaya.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan berikut. Keputusan apa yang terpaksa diambil?', '{"audio_text":"部品の供給が大幅に遅れているため、新製品の発売を延期せざるを得なくなりました。","options":[{"id":"opt_1","text":"Terpaksa menunda peluncuran produk baru"},{"id":"opt_2","text":"Mempercepat jadwal peluncuran produk baru"},{"id":"opt_3","text":"Menurunkan harga jual produk secara drastis"},{"id":"opt_4","text":"Membuka pabrik baru di luar negeri bulan ini"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '発売を延期せざるを得ない berarti terpaksa harus menunda peluncuran.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan laporan rapat berikut. Mengapa rencana proyek harus ditinjau ulang?', '{"audio_text":"予想以上にコストが膨らんだため、計画の見直しをせざるを得ない状況です。","options":[{"id":"opt_1","text":"Karena jumlah staf melebihi kapasitas kantor"},{"id":"opt_2","text":"Karena biaya membengkak jauh melampaui perkiraan"},{"id":"opt_3","text":"Karena klien membatalkan seluruh kerja sama"},{"id":"opt_4","text":"Karena produk sudah terjual habis sebelum rilis"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'コストが膨らむ (biaya membengkak) memaksa dilakukannya 計画の見直し (peninjauan ulang rencana).', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam situasi sulit seperti ini, kami terpaksa mengubah rencana awal."', '{"display_text":"このような厳しい状況では、当初の計画を変更せざるを得ません。","romaji":"Kono youna kibishii joukyou de wa, tousho no keikaku o henkou sezaru o emasen.","phonetic_breakdown":["このような","きびしい","じょうきょうでは","とうしょの","けいかくを","へんこう","せざるをえません"]}'::jsonb, '{"expected_transcript":"このような厳しい状況では、当初の計画を変更せざるを得ません。"}'::jsonb, '当初の計画 (rencana awal) dan 変更せざるを得ない (terpaksa mengubah) adalah pasangan khas N2.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih konjugasi yang benar untuk kata kerja する: 悪天候のため、本日の試合は中止___。', '{"options":["せざるを得ない","しざるを得ない","すざるを得ない","するざるを得ない"],"translation":"Karena cuaca buruk, pertandingan hari ini terpaksa dibatalkan.","sentence_template":"悪天候のため、本日の試合は中止[blank]。"}'::jsonb, '{"selected":"せざるを得ない"}'::jsonb, 'Pengecualian penting JLPT N2: する berubah menjadi せざるを得ない (bukan しざるを得ない).', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi konjugasi verba berikut: 予算が足りないため、一部の機能を___ざるを得なかった。', '{"options":["削ら","削り","削る","削れ"],"translation":"Karena anggaran tidak mencukupi, kami terpaksa memangkas sebagian fitur.","sentence_template":"予算が足りないため、一部の機能を[blank]ざるを得なかった。"}'::jsonb, '{"selected":"削ら"}'::jsonb, 'Bentuk ～ざるを得ない memakai akar bentuk ない (削る → 削らない → 削ら + ざるを得ない).', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 証拠がこれだけ揃っている以上、事実を___ざるを得ない。', '{"options":["認め","認める","認めた","認めら"],"translation":"Selama bukti sudah selengkap ini, mau tidak mau harus mengakui faktanya.","sentence_template":"証拠がこれだけ揃っている以上、事実を[blank]ざるを得ない。"}'::jsonb, '{"selected":"認め"}'::jsonb, 'Verba Ichidan 認める → akar ない adalah 認め → 認めざるを得ない.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena kereta berhenti, saya terpaksa pergi ke kantor naik taksi."', '{"tokens":["得なかった。","にあたって","止まったので、","電車が","せざるを","出社","しざるを","タクシーで"],"target_translation":"Karena kereta berhenti, saya terpaksa pergi ke kantor naik taksi.","romaji":"Densha ga tomatta node, takushii de shussha sezaru o enakatta."}'::jsonb, '["電車が","止まったので、","タクシーで","出社","せざるを","得なかった。"]'::jsonb, '出社する (pergi ke kantor) memakai bentuk せざるを得なかった.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Demi keselamatan warga, jalan ini terpaksa ditutup sementara."', '{"tokens":["この道路は","一時閉鎖","一時閉鎖し","安全のため、","住民の","に限らず","得ない。","せざるを"],"target_translation":"Demi keselamatan warga, jalan ini terpaksa ditutup sementara.","romaji":"Juumin no anzen no tame, kono douro wa ichiji heisa sezaru o enai."}'::jsonb, '["住民の","安全のため、","この道路は","一時閉鎖","せざるを","得ない。"]'::jsonb, '一時閉鎖 (penutupan sementara) + せざるを得ない menyatakan keputusan darurat.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena biaya bahan baku naik, kami terpaksa menaikkan harga jual."', '{"display_text":"原材料の高騰により、販売価格を引き上げざるを得なくなりました。","romaji":"Genzairyou no koutou ni yori, hanbai kakaku o hikiagezaru o enaku narimashita.","phonetic_breakdown":["げんざいりょうの","こうとうにより","はんばいかかくを","ひきあげざるを","えなくなりました"]}'::jsonb, '{"expected_transcript":"原材料の高騰により、販売価格を引き上げざるを得なくなりました。"}'::jsonb, '引き上げる (menaikkan harga) → 引き上げざるを得なくなる (menjadi terpaksa menaikkan).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan hasil negosiasi berikut. Apa kesimpulan pembicara?', '{"audio_text":"相手の条件には不満もあるが、納期を考えるとここで妥協せざるを得ない。","options":[{"id":"opt_1","text":"Menolak seluruh syarat dan membatalkan kontrak"},{"id":"opt_2","text":"Terpaksa berkompromi demi mengejar tenggat waktu"},{"id":"opt_3","text":"Meminta tambahan waktu selama enam bulan"},{"id":"opt_4","text":"Mengganti seluruh anggota tim negosiasi"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '妥協せざるを得ない berarti terpaksa berkompromi meski sebenarnya masih kurang puas.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan berita perusahaan berikut. Langkah apa yang terpaksa dilakukan?', '{"audio_text":"売上の減少が続いているため、不採算店舗の縮小を検討せざるを得ない状況だ。","options":[{"id":"opt_1","text":"Membuka sepuluh cabang baru di luar negeri"},{"id":"opt_2","text":"Menaikkan gaji pokok seluruh staf"},{"id":"opt_3","text":"Terpaksa mempertimbangkan penyusutan toko yang merugi"},{"id":"opt_4","text":"Mengubah nama merek perusahaan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '不採算店舗 (toko yang tidak menguntungkan) dan 縮小 (penyusutan/pengurangan).', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman kampus berikut. Mengapa kelas dipindahkan ke daring?', '{"audio_text":"大雪による交通機関の乱れが予想されるため、午後の講義はオンラインに切り替えざるを得ません。","options":[{"id":"opt_1","text":"Karena ruang kuliah sedang dipakai ujian masuk"},{"id":"opt_2","text":"Karena dosen sedang dinas ke luar negeri"},{"id":"opt_3","text":"Karena listrik di gedung kuliah padam"},{"id":"opt_4","text":"Karena gangguan transportasi akibat salju lebat diperkirakan terjadi"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '切り替える (mengalihkan) → 切り替えざるを得ない (terpaksa mengalihkan ke daring).', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kutipan laporan berikut: これ以上赤字が拡大すれば、事業の継続を___ざるを得なくなる。', '{"options":["断念せ","断念し","断念する","断念した"],"translation":"Jika defisit membesar lebih jauh lagi, kami akan terpaksa membatalkan kelanjutan bisnis ini.","sentence_template":"これ以上赤字が拡大すれば、事業の継続を[blank]ざるを得なくなる。"}'::jsonb, '{"selected":"断念せ"}'::jsonb, '断念する (membatalkan/menyerah) berubah menjadi 断念せざるを得なくなる.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 彼の主張には納得できない点もあるが、データを見る限り___ざるを得ない。', '{"options":["同意せ","同意し","同意す","同意する"],"translation":"Meski ada poin yang kurang meyakinkan dalam argumennya, melihat datanya saya terpaksa setuju.","sentence_template":"彼の主張には納得できない点もあるが、データを見る限り[blank]ざるを得ない。"}'::jsonb, '{"selected":"同意せ"}'::jsonb, '同意する (setuju) → 同意せざるを得ない.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena masalah kesehatan, saya terpaksa mengundurkan diri dari kepanitiaan."', '{"display_text":"体調不良のため、実行委員を辞退せざるを得なくなりました。","romaji":"Taichou furyou no tame, jikkou iin o jitai sezaru o enaku narimashita.","phonetic_breakdown":["たいちょうふりょうの","ため","じっこういいんを","じたい","せざるをえなく","なりました"]}'::jsonb, '{"expected_transcript":"体調不良のため、実行委員を辞退せざるを得なくなりました。"}'::jsonb, '辞退する (jitai suru) berarti mengundurkan diri secara sopan dari tawaran atau jabatan.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena kekurangan tenaga kerja, kami terpaksa mempersingkat jam operasional."', '{"tokens":["短縮","に限らず","せざるを","得ない。","ため、","短縮し","人手不足の","営業時間を"],"target_translation":"Karena kekurangan tenaga kerja, kami terpaksa mempersingkat jam operasional.","romaji":"Hitode busoku no tame, eigyou jikan o tanshuku sezaru o enai."}'::jsonb, '["人手不足の","ため、","営業時間を","短縮","せざるを","得ない。"]'::jsonb, '人手不足 (kekurangan tenaga kerja) adalah topik aktual yang sangat sering muncul di N2.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena masalah sistem, layanan terpaksa dihentikan sementara."', '{"tokens":["得なかった。","システム障害","により、","一時停止","せざるを","一時停止し","にあたって","サービスを"],"target_translation":"Karena masalah sistem, layanan terpaksa dihentikan sementara.","romaji":"Shisutemu shougai ni yori, saabisu o ichiji teishi sezaru o enakatta."}'::jsonb, '["システム障害","により、","サービスを","一時停止","せざるを","得なかった。"]'::jsonb, 'システム障害 berarti gangguan sistem.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meski menyakitkan, saya terpaksa memberitahukan fakta yang sebenarnya."', '{"tokens":["言いにくいが、","事実を","本当の","伝え","得ない。","かねない","ざるを","伝える"],"target_translation":"Meski menyakitkan, saya terpaksa memberitahukan fakta yang sebenarnya.","romaji":"Iinikui ga, hontou no jijitsu o tsutaezaru o enai."}'::jsonb, '["言いにくいが、","本当の","事実を","伝え","ざるを","得ない。"]'::jsonb, '伝える (Ichidan) → 伝えざるを得ない.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena jadwal bentrok, saya terpaksa membatalkan perjalanan dinas itu."', '{"display_text":"日程が重なってしまい、出張を取りやめざるを得なくなりました。","romaji":"Nittei ga kasanatte shimai, shucchou o toriyamezaru o enaku narimashita.","phonetic_breakdown":["にっていが","かさなってしまい","しゅっちょうを","とりやめざるを","えなくなりました"]}'::jsonb, '{"expected_transcript":"日程が重なってしまい、出張を取りやめざるを得なくなりました。"}'::jsonb, '取りやめる (membatalkan) → 取りやめざるを得なくなる.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Melihat hasil survei ini, kami terpaksa meninjau ulang strategi pemasaran."', '{"display_text":"この調査結果を見ると、販売戦略を見直さざるを得ません。","romaji":"Kono chousa kekka o miru to, hanbai senryaku o minaosa zaru o emasen.","phonetic_breakdown":["このちょうさけっかを","みると","はんばいせんりゃくを","みなおさざるを","えません"]}'::jsonb, '{"expected_transcript":"この調査結果を見ると、販売戦略を見直さざるを得ません。"}'::jsonb, '見直す (Godan) → 見直さない → 見直さざるを得ません.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena tidak ada penerbangan langsung, kami terpaksa transit di bandara lain."', '{"display_text":"直行便がないため、別の空港で乗り継がざるを得ませんでした。","romaji":"Chokkoubin ga nai tame, betsu no kuukou de noritsugazaru o emasen deshita.","phonetic_breakdown":["ちょっこうびんが","ないため","べつのくうこうで","のりつがざるを","えませんでした"]}'::jsonb, '{"expected_transcript":"直行便がないため、別の空港で乗り継がざるを得ませんでした。"}'::jsonb, '乗り継ぐ (transit/ganti pesawat) → 乗り継がない → 乗り継がざるを得ない.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 建物の老朽化が進んでおり、大規模な改修工事を___。', '{"options":["行わざるを得ない","行いざるを得ない","行うざるを得ない","行ってざるを得ない"],"translation":"Penuaan bangunan terus berlanjut sehingga kami terpaksa melakukan renovasi berskala besar.","sentence_template":"建物の老朽化が進んでおり、大規模な改修工事を[blank]。"}'::jsonb, '{"selected":"行わざるを得ない"}'::jsonb, '行う (Godan berakhiran う) bentuk ない adalah 行わない → akar 行わ + ざるを得ない.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 相手企業の倒産により、共同開発は中止___。', '{"options":["せざるを得なくなった","しざるを得なくなった","にあたった","に限らなかった"],"translation":"Akibat kebangkrutan perusahaan mitra, pengembangan bersama terpaksa dibatalkan.","sentence_template":"相手企業の倒産により、共同開発は中止[blank]。"}'::jsonb, '{"selected":"せざるを得なくなった"}'::jsonb, '中止する + ざるを得なくなる → 中止せざるを得なくなった.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar manajer berikut. Mengapa perekrutan tahun ini dikurangi?', '{"audio_text":"市場環境の変化が激しいため、今年の採用人数は当初の予定より減らさざるを得ません。","options":[{"id":"opt_1","text":"Karena perubahan lingkungan pasar sangat drastis"},{"id":"opt_2","text":"Karena tidak ada pelamar yang memenuhi syarat"},{"id":"opt_3","text":"Karena seluruh pekerjaan sudah dialihkan ke cabang luar negeri"},{"id":"opt_4","text":"Karena kantor pusat pindah ke gedung yang lebih kecil"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '市場環境の変化が激しい (perubahan pasar sangat drastis) memaksa pengurangan jumlah rekrutmen.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita berikut. Apa yang terpaksa dilakukan penduduk setempat?', '{"audio_text":"河川の水位が危険水準に達したため、住民は避難所へ移動せざるを得なくなった。","options":[{"id":"opt_1","text":"Memperbaiki jembatan secara gotong royong"},{"id":"opt_2","text":"Menutup seluruh toko selama satu bulan"},{"id":"opt_3","text":"Menghentikan penggunaan listrik di rumah"},{"id":"opt_4","text":"Berpindah ke tempat pengungsian karena permukaan sungai mencapai batas bahaya"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '避難所へ移動せざるを得なくなった berarti terpaksa berpindah ke tempat pengungsian.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena tidak ada pilihan lain, kami terpaksa menerima syarat tersebut."', '{"tokens":["受け入れ","その条件を","にあたって","ざるを","選択肢がないため、","受け入れる","他に","得ない。"],"target_translation":"Karena tidak ada pilihan lain, kami terpaksa menerima syarat tersebut.","romaji":"Hoka ni sentakushi ga nai tame, sono jouken o ukeirezaru o enai."}'::jsonb, '["他に","選択肢がないため、","その条件を","受け入れ","ざるを","得ない。"]'::jsonb, '受け入れる (Ichidan) → 受け入れざるを得ない.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya terpaksa mengakui bahwa perkiraan awal kami terlalu optimistis."', '{"display_text":"当初の見通しが甘かったことを認めざるを得ません。","romaji":"Tousho no mitooshi ga amakatta koto o mitomezaru o emasen.","phonetic_breakdown":["とうしょの","みとおしが","あまかったことを","みとめざるを","えません"]}'::jsonb, '{"expected_transcript":"当初の見通しが甘かったことを認めざるを得ません。"}'::jsonb, '見通しが甘い berarti perkiraan/proyeksi terlalu optimistis atau kurang ketat.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 激しい___にもかかわらず、多くの来場者が会場に集まった。', '{"options":["悪天候","新製品","相談室","奨学金"],"translation":"Meskipun cuaca buruk sekali, banyak pengunjung berkumpul di lokasi acara.","sentence_template":"激しい[blank]にもかかわらず、多くの来場者が会場に集まった。"}'::jsonb, '{"selected":"悪天候"}'::jsonb, '悪天候 (akutenkou) berarti cuaca buruk dan sangat sering muncul bersama ～にもかかわらず.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi berikut: 十分な___を行ったにもかかわらず、本番でトラブルが発生した。', '{"options":["検証","撤退","欠席","妥協"],"translation":"Meskipun telah dilakukan verifikasi yang memadai, gangguan tetap terjadi saat pelaksanaan utama.","sentence_template":"十分な[blank]を行ったにもかかわらず、本番でトラブルが発生した。"}'::jsonb, '{"selected":"検証"}'::jsonb, '検証 (kenshou) berarti verifikasi atau pengujian menyeluruh.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 高い___を投じたにもかかわらず、期待したほどの成果は出なかった。', '{"options":["費用","挨拶","世代","気候"],"translation":"Meskipun telah menanamkan biaya besar, hasil yang diharapkan belum tercapai.","sentence_template":"高い[blank]を投じたにもかかわらず、期待したほどの成果は出なかった。"}'::jsonb, '{"selected":"費用"}'::jsonb, '費用を投じる berarti mengalokasikan atau mengeluarkan biaya.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan sambutan pembukaan berikut. Apa yang diapresiasi oleh pembicara?', '{"audio_text":"お忙しい中にもかかわらず、本日の説明会にご参加いただき誠にありがとうございます。","options":[{"id":"opt_1","text":"Kehadiran para peserta meski di tengah kesibukan"},{"id":"opt_2","text":"Kecepatan peserta menyelesaikan tes tertulis"},{"id":"opt_3","text":"Sumbangan dana dari para sponsor acara"},{"id":"opt_4","text":"Ketepatan waktu kedatangan kereta ekspres"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'お忙しい中にもかかわらず adalah ungkapan pembuka bisnis yang sangat sopan (''meskipun di tengah kesibukan Anda'').', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan laporan penjualan berikut. Fakta kontras apa yang dilaporkan?', '{"audio_text":"価格が他社より高いにもかかわらず、品質の良さから注文が殺到している。","options":[{"id":"opt_1","text":"Pesanan menurun drastis karena kualitas kurang baik"},{"id":"opt_2","text":"Pesanan membanjir berkat kualitasnya yang unggul meski harganya lebih mahal"},{"id":"opt_3","text":"Harga produk diturunkan agar bisa bersaing dengan kompetitor"},{"id":"opt_4","text":"Pelanggan membatalkan pesanan karena pengiriman terlambat"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '注文が殺到する (pesanan membanjir) berkontras dengan 価格が高い (harga mahal).', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun hujan deras, seluruh peserta hadir tepat waktu."', '{"display_text":"激しい雨にもかかわらず、全員が時間通りに到着しました。","romaji":"Hageshii ame ni mo kakawarazu, zenin ga jikandoori ni touchaku shimashita.","phonetic_breakdown":["はげしい","あめにも","かかわらず","ぜんいんが","じかんどおりに","とうちゃくしました"]}'::jsonb, '{"expected_transcript":"激しい雨にもかかわらず、全員が時間通りに到着しました。"}'::jsonb, '時間通りに (tepat waktu) dan 到着する (tiba) adalah pasangan umum dalam laporan kegiatan.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi sambungan kata benda berikut: 深夜___にもかかわらず、駅前の通りは人通りが絶えない。', '{"options":["である","な","の","を"],"translation":"Meskipun sudah larut malam, jalan di depan stasiun tidak pernah sepi pejalan kaki.","sentence_template":"深夜[blank]にもかかわらず、駅前の通りは人通りが絶えない。"}'::jsonb, '{"selected":"である"}'::jsonb, 'Nomina dan Adjektiva-な dapat langsung diikuti にもかかわらず atau memakai であるにもかかわらず.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola kontras formal yang tepat: 何度も注意した___、同じミスが繰り返されている。', '{"options":["にもかかわらず","にあたって","に伴って","に限らず"],"translation":"Meskipun sudah berkali-kali diperingatkan, kesalahan yang sama masih terus terulang.","sentence_template":"何度も注意した[blank]、同じミスが繰り返されている。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, 'Bentuk biasa (注意した) + にもかかわらず menekankan rasa heran atau kecewa atas hasil yang bertolak belakang.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan bentuk Adjektiva-な yang benar: 立地が___にもかかわらず、そのレストランはいつも満席だ。', '{"options":["不便である","不便な","不便に","不便で"],"translation":"Meskipun lokasinya kurang strategis, restoran itu selalu penuh.","sentence_template":"立地が[blank]にもかかわらず、そのレストランはいつも満席だ。"}'::jsonb, '{"selected":"不便である"}'::jsonb, '不便 adalah Adjektiva-な; sebelum にもかかわらず, gunakan bentuk langsung (不便にもかかわらず) atau 不便であるにもかかわらず (bukan 不便な).', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun usianya masih muda, ia memimpin tim yang besar."', '{"tokens":["チームを","若い","年齢が","大きな","若くて","にもかかわらず、","にあたって、","率いている。"],"target_translation":"Meskipun usianya masih muda, ia memimpin tim yang besar.","romaji":"Nenrei ga wakai ni mo kakawarazu, ookina chiimu o hikiite iru."}'::jsonb, '["年齢が","若い","にもかかわらず、","大きな","チームを","率いている。"]'::jsonb, 'Adjektiva-い (若い) langsung diikuti にもかかわらず.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun waktu persiapan singkat, acara itu sukses besar."', '{"tokens":["短いのに","に伴って、","イベントは","だった。","短かった","準備期間が","にもかかわらず、","大成功"],"target_translation":"Meskipun waktu persiapan singkat, acara itu sukses besar.","romaji":"Junbi kikan ga mijikakatta ni mo kakawarazu, ibento wa daiseikou datta."}'::jsonb, '["準備期間が","短かった","にもかかわらず、","イベントは","大成功","だった。"]'::jsonb, 'Bentuk lampau (短かった) + にもかかわらず menyatakan kontras fakta masa lalu.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun sudah belajar keras, hasil ujian kali ini belum memuaskan."', '{"display_text":"一生懸命勉強したにもかかわらず、今回の結果は満足できませんでした。","romaji":"Isshoukenmei benkyou shita ni mo kakawarazu, konkai no kekka wa manzoku dekimasen deshita.","phonetic_breakdown":["いっしょうけんめい","べんきょうした","にもかかわらず","こんかいのけっかは","まんぞくできませんでした"]}'::jsonb, '{"expected_transcript":"一生懸命勉強したにもかかわらず、今回の結果は満足できませんでした。"}'::jsonb, '満足する (puas) sangat lazim digunakan dalam evaluasi diri maupun laporan hasil.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan berita ekonomi berikut. Fakta apa yang mengejutkan?', '{"audio_text":"景気が低迷しているにもかかわらず、高級ブランド品の売上は前年を上回った。","options":[{"id":"opt_1","text":"Penjualan barang merek mewah justru melampaui tahun lalu meski ekonomi lesu"},{"id":"opt_2","text":"Seluruh toko merek mewah tutup karena ekonomi lesu"},{"id":"opt_3","text":"Ekonomi tumbuh pesat namun penjualan barang mewah turun"},{"id":"opt_4","text":"Harga barang kebutuhan pokok turun tajam dibanding tahun lalu"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '前年を上回る berarti melampaui capaian tahun sebelumnya.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman layanan berikut. Apa yang terjadi meski pemeliharaan sudah selesai?', '{"audio_text":"システムを更新したにもかかわらず、一部の端末でログインできない不具合が続いています。","options":[{"id":"opt_1","text":"Semua pengguna sudah bisa masuk tanpa hambatan"},{"id":"opt_2","text":"Gangguan gagal masuk pada sebagian perangkat masih berlanjut"},{"id":"opt_3","text":"Pembaruan sistem ditunda hingga bulan depan"},{"id":"opt_4","text":"Seluruh perangkat lama harus diganti dengan yang baru"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '不具合 (fuguai) berarti malfungsi atau bug sistem.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar pelatih berikut. Mengapa pemain itu dipuji?', '{"audio_text":"試合の途中で足を痛めたにもかかわらず、最後まで全力で走り抜いた姿に感動しました。","options":[{"id":"opt_1","text":"Karena mencetak rekor kecepatan tertinggi pada babak pertama"},{"id":"opt_2","text":"Karena memutuskan mundur demi menjaga kondisi tim"},{"id":"opt_3","text":"Karena tetap berlari sekuat tenaga hingga akhir meski kakinya cedera"},{"id":"opt_4","text":"Karena membantu wasit mengatur jalannya pertandingan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '足を痛めたにもかかわらず (meskipun kakinya cedera) diikuti 最後まで全力で走り抜いた (berlari sekuat tenaga hingga akhir).', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kutipan artikel berikut: 事前に何度も確認した___、書類に誤字が残っていた。', '{"options":["にもかかわらず","にあたって","に限らず","に伴って"],"translation":"Meskipun telah memeriksa berkali-kali sebelumnya, masih ada salah ketik yang tertinggal di dokumen.","sentence_template":"事前に何度も確認した[blank]、書類に誤字が残っていた。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, '誤字 (goji) berarti salah ketik/salah tulis huruf.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kata hubung yang tepat di awal kalimat kedua: 昨日は大雪だった。___、電車は一本も遅れなかった。', '{"options":["それにもかかわらず","それにあたって","それに伴って","それに限らず"],"translation":"Kemarin salju turun lebat. Meskipun demikian, tidak ada satu pun kereta yang terlambat.","sentence_template":"昨日は大雪だった。[blank]、電車は一本も遅れなかった。"}'::jsonb, '{"selected":"それにもかかわらず"}'::jsonb, 'それにもかかわらず berfungsi sebagai konjungsi antarkalimat yang berarti ''meskipun demikian''.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun tidak memiliki pengalaman, ia dengan cepat menguasai pekerjaan tersebut."', '{"display_text":"未経験であるにもかかわらず、彼はすぐに業務を覚えました。","romaji":"Mikeiken de aru ni mo kakawarazu, kare wa sugu ni gyoumu o oboemashita.","phonetic_breakdown":["みけいけん","であるにも","かかわらず","かれはすぐに","ぎょうむを","おぼえました"]}'::jsonb, '{"expected_transcript":"未経験であるにもかかわらず、彼はすぐに業務を覚えました。"}'::jsonb, '未経験 (belum berpengalaman) dan 業務を覚える (menguasai tugas kerja) adalah kosakata dunia kerja.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun hari libur, banyak staf datang membantu persiapan."', '{"tokens":["スタッフが","休日","手伝った。","にあたって、","休日な","多くの","にもかかわらず、","準備を"],"target_translation":"Meskipun hari libur, banyak staf datang membantu persiapan.","romaji":"Kyuujitsu ni mo kakawarazu, ooku no sutaffu ga junbi o tetsudatta."}'::jsonb, '["休日","にもかかわらず、","多くの","スタッフが","準備を","手伝った。"]'::jsonb, '休日 (kata benda) langsung tersambung dengan にもかかわらず.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun tidak banyak beriklan, buku ini menjadi sangat laris."', '{"tokens":["宣伝を","にもかかわらず、","ベストセラーに","この本は","に伴って、","宣伝して","なった。","あまりしなかった"],"target_translation":"Meskipun tidak banyak beriklan, buku ini menjadi sangat laris.","romaji":"Senden o amari shinakatta ni mo kakawarazu, kono hon wa besutoseraa ni natta."}'::jsonb, '["宣伝を","あまりしなかった","にもかかわらず、","この本は","ベストセラーに","なった。"]'::jsonb, '宣伝 (iklan/promosi) + あまりしなかったにもかかわらず menyatakan hasil melampaui dugaan.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun cuaca sangat dingin, semua peserta maraton mencapai garis finis."', '{"tokens":["に限らず、","した。","寒さ","完走","厳しい","にもかかわらず、","全員が","寒くて"],"target_translation":"Meskipun cuaca sangat dingin, semua peserta maraton mencapai garis finis.","romaji":"Kibishii samusa ni mo kakawarazu, zenin ga kansou shita."}'::jsonb, '["厳しい","寒さ","にもかかわらず、","全員が","完走","した。"]'::jsonb, '完走する (kansou suru) berarti menyelesaikan lomba lari hingga garis finis.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih telah datang jauh-jauh meskipun jadwal Anda sangat padat."', '{"display_text":"ご多忙にもかかわらず、遠方よりお越しいただきありがとうございます。","romaji":"Gotabou ni mo kakawarazu, enpou yori okoshi itadaki arigatou gozaimasu.","phonetic_breakdown":["ごたぼうにも","かかわらず","えんぽうより","おこしいただき","ありがとうございます"]}'::jsonb, '{"expected_transcript":"ご多忙にもかかわらず、遠方よりお越しいただきありがとうございます。"}'::jsonb, 'ご多忙 (sangat sibuk, bentuk hormat) dan 遠方より (dari tempat jauh) adalah frasa bisnis tingkat tinggi.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun sudah dijelaskan berkali-kali, masih ada bagian yang kurang dipahami."', '{"display_text":"何度も説明を受けたにもかかわらず、まだ理解できない部分があります。","romaji":"Nando mo setsumei o uketa ni mo kakawarazu, mada rikai dekinai bubun ga arimasu.","phonetic_breakdown":["なんども","せつめいをうけた","にもかかわらず","まだりかいできない","ぶぶんがあります"]}'::jsonb, '{"expected_transcript":"何度も説明を受けたにもかかわらず、まだ理解できない部分があります。"}'::jsonb, '説明を受ける berarti menerima penjelasan.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun anggaran terbatas, tim kami berhasil menciptakan hasil terbaik."', '{"display_text":"予算が限られていたにもかかわらず、チームは最高の成果を出しました。","romaji":"Yosan ga kagirarete ita ni mo kakawarazu, chiimu wa saikou no seika o dashimashita.","phonetic_breakdown":["よさんが","かぎられていた","にもかかわらず","ちーむは","さいこうのせいかを","だしました"]}'::jsonb, '{"expected_transcript":"予算が限られていたにもかかわらず、チームは最高の成果を出しました。"}'::jsonb, '成果を出す berarti menghasilkan capaian/kinerja nyata.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 彼はまだ来日して一年___にもかかわらず、日本語のニュースを正確に理解できる。', '{"options":["である","な","の","を"],"translation":"Meskipun baru satu tahun datang ke Jepang, ia dapat memahami berita bahasa Jepang secara akurat.","sentence_template":"彼はまだ来日して一年[blank]にもかかわらず、日本語のニュースを正確に理解できる。"}'::jsonb, '{"selected":"である"}'::jsonb, 'Kata benda 一年 diikuti であるにもかかわらず (atau langsung 一年にもかかわらず).', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 医師から安静にするよう言われた___、彼は仕事を続けてしまった。', '{"options":["にもかかわらず","にあたって","に伴って","に限らず"],"translation":"Meskipun sudah diminta dokter untuk beristirahat total, ia tetap saja melanjutkan bekerja.","sentence_template":"医師から安静にするよう言われた[blank]、彼は仕事を続けてしまった。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, '安静にする (beristirahat tenang/bed rest) + 言われたにもかかわらず menekankan tindakan yang bertentangan dengan saran.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan cuaca berikut. Apa yang terjadi meski peringatan sudah dikeluarkan?', '{"audio_text":"大雨警報が出ていたにもかかわらず、川に近づいて救助される事故が相次いだ。","options":[{"id":"opt_1","text":"Semua warga tetap berada di dalam rumah dengan aman"},{"id":"opt_2","text":"Terjadi serangkaian insiden orang mendekati sungai hingga harus diselamatkan"},{"id":"opt_3","text":"Peringatan hujan lebat dicabut lebih cepat dari jadwal"},{"id":"opt_4","text":"Air sungai justru surut drastis sepanjang malam"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '相次ぐ (aitsugu) berarti terjadi berturut-turut; 救助される berarti diselamatkan.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan film berikut. Apa keunikan film tersebut?', '{"audio_text":"有名な俳優が出ていないにもかかわらず、口コミで評判が広がり大ヒットとなった。","options":[{"id":"opt_1","text":"Film itu gagal total karena kurang promosi televisi"},{"id":"opt_2","text":"Film itu dibintangi puluhan aktor papan atas dunia"},{"id":"opt_3","text":"Film itu hanya diputar selama tiga hari di bioskop kecil"},{"id":"opt_4","text":"Film itu menjadi hit besar lewat rekomendasi dari mulut ke mulut meski tanpa aktor terkenal"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '口コミ (kuchikomi) berarti informasi dari mulut ke mulut.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun sudah larut malam, ia membalas email saya dengan cepat."', '{"tokens":["すぐに","くれた。","に伴って、","時間","返信を","夜遅い","にもかかわらず、","時間な"],"target_translation":"Meskipun sudah larut malam, ia membalas email saya dengan cepat.","romaji":"Yoru osoi jikan ni mo kakawarazu, sugu ni henshin o kureta."}'::jsonb, '["夜遅い","時間","にもかかわらず、","すぐに","返信を","くれた。"]'::jsonb, '返信をくれる berarti membalas pesan/email untuk saya.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun ini percobaan pertama, semuanya berjalan lebih lancar dari dugaan."', '{"display_text":"初めての試みにもかかわらず、予想以上に順調に進みました。","romaji":"Hajimete no kokoromi ni mo kakawarazu, yosou ijou ni junchou ni susumimashita.","phonetic_breakdown":["はじめての","こころみにも","かかわらず","よそういじょうに","じゅんちょうに","すすみました"]}'::jsonb, '{"expected_transcript":"初めての試みにもかかわらず、予想以上に順調に進みました。"}'::jsonb, '試み (kokoromi) berarti upaya/inisiatif baru; 順調に進む berarti berjalan lancar.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: チーム全員で十分に___した上で、最終案を決定した。', '{"options":["検討","欠席","撤退","渋滞"],"translation":"Setelah seluruh tim mempertimbangkan secara matang, kami memutuskan draf final.","sentence_template":"チーム全員で十分に[blank]した上で、最終案を決定した。"}'::jsonb, '{"selected":"検討"}'::jsonb, '検討する (kentou suru) berarti meninjau atau mempertimbangkan secara mendalam sebelum mengambil keputusan.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 契約書の条項をすべて___した上で、署名してください。', '{"options":["確認","延期","普及","卒業"],"translation":"Silakan tanda tangan setelah memastikan seluruh pasal dalam surat kontrak.","sentence_template":"契約書の条項をすべて[blank]した上で、署名してください。"}'::jsonb, '{"selected":"確認"}'::jsonb, '条項 (joukou) adalah pasal/klausul; 確認した上で berarti ''setelah memastikan''.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 海外で働く上で、現地の商習慣への___が欠かせない。', '{"options":["理解","物価","天候","予算"],"translation":"Dalam bekerja di luar negeri, pemahaman terhadap kebiasaan bisnis lokal tidak boleh terlewatkan.","sentence_template":"海外で働く上で、現地の商習慣への[blank]が欠かせない。"}'::jsonb, '{"selected":"理解"}'::jsonb, '商習慣 (shoushuukan) berarti adat/kebiasaan bisnis; 理解 berarti pemahaman.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan arahan manajer berikut. Kapan keputusan akhir akan dibuat?', '{"audio_text":"来週の会議で各部署の意見を聞いた上で、正式なスケジュールを決定します。","options":[{"id":"opt_1","text":"Setelah mendengarkan pendapat tiap departemen pada rapat minggu depan"},{"id":"opt_2","text":"Hari ini juga sebelum jam makan siang berakhir"},{"id":"opt_3","text":"Bulan depan setelah laporan keuangan tahunan terbit"},{"id":"opt_4","text":"Segera tanpa perlu berkonsultasi dengan departemen lain"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '意見を聞いた上で (setelah mendengarkan pendapat) menunjukkan syarat sebelum keputusan resmi dibuat.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan nasihat dosen berikut. Hal apa yang penting saat menulis karya ilmiah?', '{"audio_text":"論文を書く上で、信頼できる参考文献を選ぶことが何よりも重要です。","options":[{"id":"opt_1","text":"Membuat sampul berwarna cerah"},{"id":"opt_2","text":"Memilih daftar pustaka yang tepercaya"},{"id":"opt_3","text":"Menulis dengan jumlah halaman seminimal mungkin"},{"id":"opt_4","text":"Menggunakan bahasa percakapan sehari-hari"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '論文を書く上で (dalam menulis makalah ilmiah) + 信頼できる参考文献 (referensi yang dapat dipercaya).', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah berdiskusi dengan keluarga, saya memutuskan untuk melamar pekerjaan ini."', '{"display_text":"家族と相談した上で、この会社に応募することにしました。","romaji":"Kazoku to soudan shita ue de, kono kaisha ni oubo suru koto ni shimashita.","phonetic_breakdown":["かぞくと","そうだんした","うえで","このかいしゃに","おうぼすることに","しました"]}'::jsonb, '{"expected_transcript":"家族と相談した上で、この会社に応募することにしました。"}'::jsonb, '相談した上で (setelah berkonsultasi) dan 応募する (melamar pekerjaan/beasiswa).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk verba yang tepat untuk makna ''setelah melakukan A, lalu B'': リスクを十分に___上で、投資の判断を下すべきだ。', '{"options":["把握した","把握する","把握して","把握しない"],"translation":"Sebaiknya mengambil keputusan investasi setelah memahami risikonya secara menyeluruh.","sentence_template":"リスクを十分に[blank]上で、投資の判断を下すべきだ。"}'::jsonb, '{"selected":"把握した"}'::jsonb, 'Untuk menyatakan urutan ''setelah menyelesaikan A baru melakukan B'', gunakan V-た + 上で.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk verba untuk makna ''dalam hal / saat menjalankan'': プロジェクトを___上で、チーム間の情報共有が最も大切だ。', '{"options":["進める","進めた","進めて","進めない"],"translation":"Dalam menjalankan proyek, berbagi informasi antartim adalah hal yang paling penting.","sentence_template":"プロジェクトを[blank]上で、チーム間の情報共有が最も大切だ。"}'::jsonb, '{"selected":"進める"}'::jsonb, 'Untuk menyatakan ruang lingkup ''dalam hal melakukan...'', gunakan V-dict (進める) + 上で.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi sambungan kata benda berikut: 健康管理___上で、規則正しい睡眠は基本中の基本だ。', '{"options":["の","な","に","を"],"translation":"Dalam hal pengelolaan kesehatan, tidur yang teratur adalah dasar dari segala dasar.","sentence_template":"健康管理[blank]上で、規則正しい睡眠は基本中の基本だ。"}'::jsonb, '{"selected":"の"}'::jsonb, 'Kata benda selalu disambungkan dengan partikel の sebelum 上で (健康管理の上で).', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setelah membaca petunjuk dengan teliti, silakan mulai tesnya."', '{"tokens":["始めてください。","説明書を","上で、","読んだ","読む","よく","に限らず、","テストを"],"target_translation":"Setelah membaca petunjuk dengan teliti, silakan mulai tesnya.","romaji":"Setsumeisho o yoku yonda ue de, tesuto o hajimete kudasai."}'::jsonb, '["説明書を","よく","読んだ","上で、","テストを","始めてください。"]'::jsonb, '読んだ上で menekankan bahwa membaca petunjuk adalah prasyarat sebelum memulai tes.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam bekerja di Jepang, pemahaman etika bisnis sangatlah berguna."', '{"tokens":["日本で","働く","上で、","役立つ。","ビジネスマナーの","にもかかわらず、","働いた","知識が"],"target_translation":"Dalam bekerja di Jepang, pemahaman etika bisnis sangatlah berguna.","romaji":"Nihon de hataraku ue de, bijinesu manaa no chishiki ga yakudatsu."}'::jsonb, '["日本で","働く","上で、","ビジネスマナーの","知識が","役立つ。"]'::jsonb, '働く上で (dalam hal bekerja) memakai bentuk kamus.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah memeriksa rincian biaya, kami akan mengirimkan surat penawaran resmi."', '{"display_text":"費用の詳細を確認した上で、正式なお見積書をお送りします。","romaji":"Hiyou no shousai o kakunin shita ue de, seishikina omitsumorisho o ookuri shimasu.","phonetic_breakdown":["ひようの","しょうさいを","かくにんした","うえで","せいしきな","おみつもりしょを","おおくりします"]}'::jsonb, '{"expected_transcript":"費用の詳細を確認した上で、正式なお見積書をお送りします。"}'::jsonb, '見積書 (mitsumorisho) berarti surat penawaran harga/estimasi biaya dalam bisnis Jepang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan agen properti berikut. Apa yang disarankan sebelum menyewa apartemen?', '{"audio_text":"実際に部屋を見学した上で、契約するかどうかを決めたほうがいいですよ。","options":[{"id":"opt_1","text":"Langsung mentransfer uang muka tanpa melihat kamar"},{"id":"opt_2","text":"Memutuskan kontrak setelah benar-benar meninjau kamar secara langsung"},{"id":"opt_3","text":"Menandatangani kontrak jangka panjang selama sepuluh tahun"},{"id":"opt_4","text":"Meminta teman memilihkan kamar lewat foto saja"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '見学した上で berarti ''setelah meninjau langsung''.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar manajer HRD berikut. Apa yang dianggap penting dalam kepemimpinan?', '{"audio_text":"部下を指導する上で、相手の話を最後まで聞く姿勢が不可欠です。","options":[{"id":"opt_1","text":"Memberi tugas sebanyak mungkin setiap hari"},{"id":"opt_2","text":"Menghindari rapat tatap muka dengan anggota tim"},{"id":"opt_3","text":"Sikap mendengarkan perkataan lawan bicara hingga selesai saat membimbing bawahan"},{"id":"opt_4","text":"Membuat aturan tertulis sepanjang seratus halaman"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '部下を指導する上で berarti ''dalam hal membimbing bawahan''.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman rapat berikut. Apa yang akan dilakukan setelah melihat data survei?', '{"audio_text":"顧客アンケートの結果を分析した上で、来月の改善策をまとめる予定です。","options":[{"id":"opt_1","text":"Menghentikan seluruh layanan pelanggan mulai minggu depan"},{"id":"opt_2","text":"Membagikan hadiah kepada seluruh responden survei"},{"id":"opt_3","text":"Menghapus hasil survei yang lama dari server"},{"id":"opt_4","text":"Merangkum langkah perbaikan bulan depan setelah menganalisis hasil survei pelanggan"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '分析した上で (setelah menganalisis) → 改善策をまとめる (merangkum rencana perbaikan).', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 複数の会社の条件を___上で、最も適した取引先を選んだ。', '{"options":["比較した","比較する","比較して","比較せず"],"translation":"Setelah membandingkan ketentuan beberapa perusahaan, kami memilih mitra bisnis yang paling sesuai.","sentence_template":"複数の会社の条件を[blank]上で、最も適した取引先を選んだ。"}'::jsonb, '{"selected":"比較した"}'::jsonb, 'Urutan aksi ''membandingkan dulu, lalu memilih'' memakai bentuk lampau 比較した上で.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 国際ビジネスを展開___上で、現地法規の遵守は絶対条件だ。', '{"options":["する","した","して","された"],"translation":"Dalam mengembangkan bisnis internasional, kepatuhan terhadap hukum setempat adalah syarat mutlak.","sentence_template":"国際ビジネスを展開[blank]上で、現地法規の遵守は絶対条件だ。"}'::jsonb, '{"selected":"する"}'::jsonb, '展開する上で menyatakan ruang lingkup/konteks ''dalam mengembangkan...''.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah memahami risiko dan manfaatnya, mari kita ambil keputusan."', '{"display_text":"メリットとデメリットを理解した上で、判断しましょう。","romaji":"Meritto to demeritto o rikai shita ue de, handan shimashou.","phonetic_breakdown":["めりっとと","でめりっとを","りかいした","うえで","はんだんしましょう"]}'::jsonb, '{"expected_transcript":"メリットとデメリットを理解した上で、判断しましょう。"}'::jsonb, 'メリット (kelebihan) dan デメリット (kekurangan) sangat umum dalam rapat bisnis Jepang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setelah mendengarkan laporan lapangan, kami menyusun langkah berikutnya."', '{"tokens":["報告を","立てた。","聞く","現場の","にあたって、","上で、","聞いた","次の対策を"],"target_translation":"Setelah mendengarkan laporan lapangan, kami menyusun langkah berikutnya.","romaji":"Genba no houkoku o kiita ue de, tsugi no taisaku o tateta."}'::jsonb, '["現場の","報告を","聞いた","上で、","次の対策を","立てた。"]'::jsonb, '現場 (genba) berarti lokasi kerja/lapangan; 聞いた上で berarti setelah mendengar.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam menjaga keamanan data, pengelolaan kata sandi sangat penting."', '{"tokens":["の","パスワードの","保護が","に伴って、","極めて重要だ。","データ管理","な","上で、"],"target_translation":"Dalam menjaga keamanan data, pengelolaan kata sandi sangat penting.","romaji":"Deeta kanri no ue de, pasuwaado no hogo ga kiwamete juuyou da."}'::jsonb, '["データ管理","の","上で、","パスワードの","保護が","極めて重要だ。"]'::jsonb, 'データ管理の上で memakai partikel の setelah kata benda.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setelah mendapatkan persetujuan atasan, saya akan mengirim email ke klien."', '{"tokens":["連絡します。","上で、","得る","上司の","顧客へ","得た","に限らず、","承認を"],"target_translation":"Setelah mendapatkan persetujuan atasan, saya akan mengirim email ke klien.","romaji":"Joushi no shounin o eta ue de, kokyaku e renraku shimasu."}'::jsonb, '["上司の","承認を","得た","上で、","顧客へ","連絡します。"]'::jsonb, '承認を得る (mendapatkan persetujuan) → 承認を得た上で.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam belajar bahasa asing, keberanian untuk tidak takut salah itu penting."', '{"display_text":"外国語を学ぶ上で、間違いを恐れない姿勢が大切です。","romaji":"Gaikokugo o manabu ue de, machigai o osorenai shisei ga taisetsu desu.","phonetic_breakdown":["がいこくごを","まなぶ","うえで","まちがいを","おそれない","しせいがたいせつです"]}'::jsonb, '{"expected_transcript":"外国語を学ぶ上で、間違いを恐れない姿勢が大切です。"}'::jsonb, '間違いを恐れない (tidak takut membuat kesalahan) + 学ぶ上で.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah meninjau isi proposal, kami akan menghubungi Anda kembali besok."', '{"display_text":"ご提案の内容を精査した上で、明日改めてご連絡いたします。","romaji":"Goteian no naiyou o seisa shita ue de, asu aratamete gorenraku itashimasu.","phonetic_breakdown":["ごていあんの","ないようを","せいさしたうえで","あすあらためて","ごれんらくいたします"]}'::jsonb, '{"expected_transcript":"ご提案の内容を精査した上で、明日改めてご連絡いたします。"}'::jsonb, '精査する (seisa suru) berarti memeriksa secara saksama; 改めて berarti kembali/di lain waktu.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam menjalankan kehidupan di Jepang, memahami aturan pemilahan sampah itu perlu."', '{"display_text":"日本で生活する上で、ゴミ分別のルールを知る必要があります。","romaji":"Nihon de seikatsu suru ue de, gomi bunbetsu no ruuru o shiru hitsuyou ga arimasu.","phonetic_breakdown":["にほんで","せいかつする","うえで","ごみぶんべつの","るーるをしる","ひつようがあります"]}'::jsonb, '{"expected_transcript":"日本で生活する上で、ゴミ分別のルールを知る必要があります。"}'::jsonb, 'ゴミ分別 (pemilahan sampah) adalah bagian penting dari kehidupan sehari-hari di Jepang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 双方の合意を___上で、正式な契約書に調印した。', '{"options":["確認した","確認する","確認して","確認せず"],"translation":"Setelah memastikan kesepakatan kedua belah pihak, kami menandatangani surat kontrak resmi.","sentence_template":"双方の合意を[blank]上で、正式な契約書に調印した。"}'::jsonb, '{"selected":"確認した"}'::jsonb, '調印する (menandatangani perjanjian resmi) dilakukan setelah 合意を確認した (memastikan kesepakatan).', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 企業を経営___上で、法令遵守と顧客からの信頼は欠かせない。', '{"options":["する","した","して","された"],"translation":"Dalam mengelola perusahaan, kepatuhan hukum dan kepercayaan pelanggan tidak boleh terlewatkan.","sentence_template":"企業を経営[blank]上で、法令遵守と顧客からの信頼は欠かせない。"}'::jsonb, '{"selected":"する"}'::jsonb, '経営する上で berarti ''dalam hal mengelola (perusahaan)''.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan arahan rapat berikut. Apa langkah pertama sebelum mengubah anggaran?', '{"audio_text":"現状の支出データをすべて洗い出した上で、来期の予算配分を見直しましょう。","options":[{"id":"opt_1","text":"Mendata secara menyeluruh seluruh data pengeluaran saat ini"},{"id":"opt_2","text":"Langsung memotong anggaran promosi sebesar lima puluh persen"},{"id":"opt_3","text":"Menunda rapat anggaran hingga kuartal berikutnya"},{"id":"opt_4","text":"Meminta pinjaman baru dari bank sebelum rapat dimulai"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '洗い出す (araidasu) berarti membongkar/mendata secara menyeluruh tanpa terlewat.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan saran karier berikut. Apa yang penting dalam membangun jaringan kerja?', '{"audio_text":"長期的なキャリアを築く上で、社外の専門家との人脈づくりも非常に有効です。","options":[{"id":"opt_1","text":"Hanya bergaul dengan rekan satu ruangan saja"},{"id":"opt_2","text":"Sering berpindah pekerjaan setiap tiga bulan"},{"id":"opt_3","text":"Membangun jejaring dengan para ahli di luar perusahaan"},{"id":"opt_4","text":"Menghindari seminar dan konferensi industri"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '人脈づくり (membangun jaringan relasi) sangat efektif dalam キャリアを築く上で (membangun karier jangka panjang).', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setelah berdiskusi dengan dosen, saya menetapkan tema penelitian."', '{"tokens":["研究テーマを","話し合う","にもかかわらず、","教授と","上で、","話し合った","決定","した。"],"target_translation":"Setelah berdiskusi dengan dosen, saya menetapkan tema penelitian.","romaji":"Kyouju to hanashiatta ue de, kenkyuu teema o kettei shita."}'::jsonb, '["教授と","話し合った","上で、","研究テーマを","決定","した。"]'::jsonb, '話し合った上で berarti setelah berdiskusi bersama.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah memahami syarat dan ketentuan, silakan tekan tombol setuju."', '{"display_text":"利用規約をご確認いただいた上で、同意ボタンを押してください。","romaji":"Riyou kiyaku o gokakunin itadaita ue de, doui botan o oshite kudasai.","phonetic_breakdown":["りようきやくを","ごかくにんいただいた","うえで","どういぼたんを","おしてください"]}'::jsonb, '{"expected_transcript":"利用規約をご確認いただいた上で、同意ボタンを押してください。"}'::jsonb, '利用規約 (syarat dan ketentuan layanan) sangat sering ditemui pada situs web dan aplikasi Jepang.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 再生可能エネルギーへの___が世界規模で進みつつある。', '{"options":["移行","欠席","挨拶","妥協"],"translation":"Transisi menuju energi terbarukan sedang terus berlangsung dalam skala global.","sentence_template":"再生可能エネルギーへの[blank]が世界規模で進みつつある。"}'::jsonb, '{"selected":"移行"}'::jsonb, '移行 (ikou) berarti peralihan atau transisi dari sistem lama ke sistem baru.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berita berikut: 経済状況は緩やかに___しつつあると報告された。', '{"options":["回復","中止","撤退","閉会"],"translation":"Dilaporkan bahwa kondisi ekonomi sedang berangsur-angsur pulih.","sentence_template":"経済状況は緩やかに[blank]しつつあると報告された。"}'::jsonb, '{"selected":"回復"}'::jsonb, '回復する (kaifuku suru) berarti pulih; 緩やかに berarti secara perlahan/bertahap.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 地域の伝統文化が担い手不足により___しつつある。', '{"options":["衰退","普及","拡大","発展"],"translation":"Budaya tradisional daerah sedang terus mengalami kemunduran akibat kurangnya penerus.","sentence_template":"地域の伝統文化が担い手不足により[blank]しつつある。"}'::jsonb, '{"selected":"衰退"}'::jsonb, '衰退 (suitai) berarti kemunduran atau penyusutan; 担い手 berarti penerus/pelaku.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan berita sosial berikut. Perubahan apa yang sedang berlangsung?', '{"audio_text":"近年、キャッシュレス決済が地方の個人商店にも定着しつつあります。","options":[{"id":"opt_1","text":"Pembayaran nontunai sedang mulai mengakar hingga ke toko perorangan di daerah"},{"id":"opt_2","text":"Toko di daerah mulai menolak semua kartu kredit"},{"id":"opt_3","text":"Uang tunai kembali menjadi satu-satunya alat pembayaran"},{"id":"opt_4","text":"Jumlah toko perorangan meningkat dua kali lipat tahun ini"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '定着しつつある berarti sedang berproses mengakar/menjadi kebiasaan tetap.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan laporan lingkungan berikut. Apa yang sedang terjadi di laut?', '{"audio_text":"海水温の上昇により、一部の魚種の生息域が北へ移動しつつある。","options":[{"id":"opt_1","text":"Jumlah kapal penangkap ikan berkurang drastis"},{"id":"opt_2","text":"Habitat sebagian jenis ikan sedang bergeser ke arah utara"},{"id":"opt_3","text":"Suhu air laut turun di bawah rata-rata musiman"},{"id":"opt_4","text":"Polusi plastik di laut sudah sepenuhnya hilang"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '移動しつつある berarti sedang terus berpindah/bergeser secara bertahap.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Nilai-nilai masyarakat mengenai cara bekerja sedang berubah perlahan."', '{"display_text":"働き方に対する社会の価値観は、少しずつ変わりつつあります。","romaji":"Hatarakikata ni taisuru shakai no kachikan wa, sukoshizutsu kawari tsutsu arimasu.","phonetic_breakdown":["はたらきかたに","たいする","しゃかいのかちかんは","すこしずつ","かわりつつあります"]}'::jsonb, '{"expected_transcript":"働き方に対する社会の価値観は、少しずつ変わりつつあります。"}'::jsonb, '価値観 (kachikan) berarti nilai-nilai atau cara pandang; 変わりつつある berarti sedang terus berubah.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih konjugasi yang benar untuk ～つつある: 地球温暖化の影響は、年々深刻に___つつある。', '{"options":["なり","なる","なった","なって"],"translation":"Dampak pemanasan global sedang menjadi semakin serius dari tahun ke tahun.","sentence_template":"地球温暖化の影響は、年々深刻に[blank]つつある。"}'::jsonb, '{"selected":"なり"}'::jsonb, 'Pola ～つつある selalu menempel pada akar bentuk ます (なる → なります → なりつつある).', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 長年の研究の成果が、ようやく実用化___つつある。', '{"options":["され","する","した","して"],"translation":"Hasil penelitian bertahun-tahun akhirnya sedang mulai diterapkan secara praktis.","sentence_template":"長年の研究の成果が、ようやく実用化[blank]つつある。"}'::jsonb, '{"selected":"され"}'::jsonb, '実用化される (diterapkan secara praktis) → akar ます adalah 実用化され → 実用化されつつある.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang paling tepat: 少子化の影響で、地方の学校の統廃合が___。', '{"options":["進みつつある","進みたつつある","進むつつある","進んでつつある"],"translation":"Akibat penurunan angka kelahiran, penggabungan dan penutupan sekolah daerah sedang terus berlanjut.","sentence_template":"少子化の影響で、地方の学校の統廃合が[blank]。"}'::jsonb, '{"selected":"進みつつある"}'::jsonb, '進む → 進みます → 進みつつある.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Lingkungan bisnis di industri ini sedang mengalami perubahan besar."', '{"tokens":["しつつ","にあたって","この業界の","ビジネス環境は","大きく","変化して","ある。","変化"],"target_translation":"Lingkungan bisnis di industri ini sedang mengalami perubahan besar.","romaji":"Kono gyoukai no bijinesu kankyou wa ookiku henka shitsutsu aru."}'::jsonb, '["この業界の","ビジネス環境は","大きく","変化","しつつ","ある。"]'::jsonb, '変化する → 変化します → 変化しつつある.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Penggunaan kendaraan listrik sedang meluas secara bertahap di seluruh dunia."', '{"tokens":["徐々に","広がり","利用が","つつある。","広がる","電気自動車の","に限らず","世界中で"],"target_translation":"Penggunaan kendaraan listrik sedang meluas secara bertahap di seluruh dunia.","romaji":"Denki jidousha no riyou ga sekaijuu de jojo ni hirogaritsutsu aru."}'::jsonb, '["電気自動車の","利用が","世界中で","徐々に","広がり","つつある。"]'::jsonb, '徐々に (secara bertahap) sering berkolokasi dengan ～つつある.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kepercayaan pelanggan terhadap merek kami sedang berangsur pulih."', '{"display_text":"当社ブランドへの顧客の信頼は、着実に回復しつつあります。","romaji":"Tousha burando e no kokyaku no shinrai wa, chakujitsu ni kaifuku shitsutsu arimasu.","phonetic_breakdown":["とうしゃぶらんどえの","こきゃくのしんらいは","ちゃくじつに","かいふくしつつ","あります"]}'::jsonb, '{"expected_transcript":"当社ブランドへの顧客の信頼は、着実に回復しつつあります。"}'::jsonb, '着実に (chakujitsu ni) berarti secara mantap dan pasti.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan berita industri berikut. Apa yang sedang terjadi di pabrik-pabrik modern?', '{"audio_text":"人手不足を補うため、多くの製造現場でロボットによる自動化が進みつつある。","options":[{"id":"opt_1","text":"Otomatisasi dengan robot sedang berkembang di banyak pabrik untuk menutupi kekurangan tenaga kerja"},{"id":"opt_2","text":"Seluruh pabrik menghentikan penggunaan mesin otomatis"},{"id":"opt_3","text":"Jumlah pekerja pabrik meningkat tajam dibanding dekade lalu"},{"id":"opt_4","text":"Produksi barang manufaktur dipindahkan sepenuhnya ke rumah tangga"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'ロボットによる自動化が進みつつある berarti otomatisasi oleh robot sedang terus berjalan.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan laporan pendidikan berikut. Tren apa yang dibahas?', '{"audio_text":"デジタル教材の普及により、学校の授業スタイルも大きく様変わりしつつあります。","options":[{"id":"opt_1","text":"Sekolah melarang penggunaan tablet di dalam kelas"},{"id":"opt_2","text":"Jumlah jam pelajaran dikurangi setengahnya"},{"id":"opt_3","text":"Gaya pembelajaran di sekolah sedang berubah besar berkat bahan ajar digital"},{"id":"opt_4","text":"Buku tulis kertas kembali diwajibkan untuk semua ujian"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '様変わりする (samagawari suru) berarti berubah wujud/wajah secara drastis.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan berita perkotaan berikut. Perubahan apa yang sedang terjadi di distrik tua?', '{"audio_text":"再開発計画の進行に伴い、歴史ある商店街の風景が少しずつ失われつつある。","options":[{"id":"opt_1","text":"Jumlah toko tradisional bertambah dua kali lipat"},{"id":"opt_2","text":"Rencana pembangunan ulang dibatalkan oleh pemerintah kota"},{"id":"opt_3","text":"Harga sewa toko diturunkan untuk menarik pedagang baru"},{"id":"opt_4","text":"Pemandangan jalan pertokoan bersejarah sedang perlahan menghilang"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '失われつつある (sedang perlahan hilang) menggambarkan perubahan yang memprihatinkan.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 新しい治療法の開発により、かつての不治の病も克服___つつある。', '{"options":["され","し","する","した"],"translation":"Berkat pengembangan metode pengobatan baru, penyakit yang dulu tak tersembuhkan pun sedang mulai teratasi.","sentence_template":"新しい治療法の開発により、かつての不治の病も克服[blank]つつある。"}'::jsonb, '{"selected":"され"}'::jsonb, '克服される (diatasi/ditaklukkan) → 克服されつつある.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih verba penghubung yang tepat: 地域のコミュニティのつながりが、近年薄れ___ある。', '{"options":["つつ","ながら","ばかり","どころか"],"translation":"Ikatan komunitas lokal sedang perlahan memudar dalam beberapa tahun terakhir.","sentence_template":"地域のコミュニティのつながりが、近年薄れ[blank]ある。"}'::jsonb, '{"selected":"つつ"}'::jsonb, '薄れる (usureru, memudar) + つつある menunjukkan proses pelemahan yang berlangsung bertahap.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Teknologi terjemahan otomatis sedang berkembang pesat setiap harinya."', '{"display_text":"自動翻訳の精度は、日々急速に向上しつつあります。","romaji":"Jidou honyaku no seido wa, hibi kyuusoku ni koujou shitsutsu arimasu.","phonetic_breakdown":["じどうほんやくの","せいどは","ひびきゅうそくに","こうじょうしつつ","あります"]}'::jsonb, '{"expected_transcript":"自動翻訳の精度は、日々急速に向上しつつあります。"}'::jsonb, '精度 (akurasi/presisi) dan 向上する (meningkat) adalah kosakata kunci bidang teknologi.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kesadaran akan pentingnya kesehatan mental sedang meningkat di tempat kerja."', '{"tokens":["メンタルヘルスへの","高まり","つつ","かねない","職場での","高まる","意識が","ある。"],"target_translation":"Kesadaran akan pentingnya kesehatan mental sedang meningkat di tempat kerja.","romaji":"Shokuba de no mentaru herusu e no ishiki ga takamaritsutsu aru."}'::jsonb, '["職場での","メンタルヘルスへの","意識が","高まり","つつ","ある。"]'::jsonb, '高まる (meningkat) → 高まりつつある.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Upaya mengurangi sampah plastik sedang menyebar ke seluruh lapisan masyarakat."', '{"tokens":["社会全体に","にあたって","減らす","取り組みが","しつつある。","プラスチックごみを","浸透","浸透した"],"target_translation":"Upaya mengurangi sampah plastik sedang menyebar ke seluruh lapisan masyarakat.","romaji":"Purasuchikku gomi o herasu torikumi ga shakai zentai ni shintou shitsutsu aru."}'::jsonb, '["プラスチックごみを","減らす","取り組みが","社会全体に","浸透","しつつある。"]'::jsonb, '浸透する (shintou suru) berarti meresap/menyebar luas.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sistem kerja fleksibel sedang mulai diterapkan di banyak perusahaan Jepang."', '{"tokens":["勤務制度が","日本企業で","導入して","柔軟な","導入","に限らず","されつつある。","多くの"],"target_translation":"Sistem kerja fleksibel sedang mulai diterapkan di banyak perusahaan Jepang.","romaji":"Juunanna kinmu seido ga ooku no Nihon kigyou de dounyuu saretsutsu aru."}'::jsonb, '["柔軟な","勤務制度が","多くの","日本企業で","導入","されつつある。"]'::jsonb, '柔軟な勤務制度 berarti sistem kerja yang fleksibel.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Proyek pembangunan jembatan baru akhirnya sedang mendekati tahap penyelesaian."', '{"display_text":"新しい橋の建設工事は、ようやく完成に近づきつつあります。","romaji":"Atarashii hashi no kensetsu kouji wa, youyaku kansei ni chikazukitsutsu arimasu.","phonetic_breakdown":["あたらしいはしの","けんせつこうじは","ようやく","かんせいに","ちかづきつつあります"]}'::jsonb, '{"expected_transcript":"新しい橋の建設工事は、ようやく完成に近づきつつあります。"}'::jsonb, '完成に近づく (mendekati penyelesaian) → 近づきつつある.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Perbedaan antara bekerja di kantor dan dari rumah sedang semakin kabur."', '{"display_text":"オフィス勤務と在宅勤務の境界は、次第に曖昧になりつつあります。","romaji":"Ofisu kinmu to zaitaku kinmu no kyoukai wa, shidai ni aimai ni naritsutsu arimasu.","phonetic_breakdown":["おふぃすきんむと","ざいたくきんむの","きょうかいは","しだいに","あいまいになりつつあります"]}'::jsonb, '{"expected_transcript":"オフィス勤務と在宅勤務の境界は、次第に曖昧になりつつあります。"}'::jsonb, '次第に (lambat laun) dan 曖昧 (kabur/tidak tegas) cocok dengan ～つつある.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kerja sama penelitian antara universitas dan industri sedang semakin erat."', '{"display_text":"大学と企業の共同研究は、今後さらに活発になりつつあります。","romaji":"Daigaku to kigyou no kyoudou kenkyuu wa, kongo sara ni kappatsu ni naritsutsu arimasu.","phonetic_breakdown":["だいがくときぎょうの","きょうどうけんきゅうは","こんごさらに","かっぱつに","なりつつあります"]}'::jsonb, '{"expected_transcript":"大学と企業の共同研究は、今後さらに活発になりつつあります。"}'::jsonb, '活発になる (menjadi aktif/giat) → 活発になりつつある.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 人口減少により、地方の公共交通機関の維持が難しく___。', '{"options":["なりつつある","なるつつある","なったつつある","なってつつある"],"translation":"Akibat penurunan populasi, mempertahankan transportasi umum di daerah sedang menjadi makin sulit.","sentence_template":"人口減少により、地方の公共交通機関の維持が難しく[blank]。"}'::jsonb, '{"selected":"なりつつある"}'::jsonb, '難しくなる → 難しくなりつつある.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berita berikut: 国際的な協調により、新たな安全基準が___つつある。', '{"options":["整えられ","整える","整えた","整えて"],"translation":"Melalui kerja sama internasional, standar keamanan baru sedang mulai ditata.","sentence_template":"国際的な協調により、新たな安全基準が[blank]つつある。"}'::jsonb, '{"selected":"整えられ"}'::jsonb, '整えられる (ditata/disiapkan, bentuk pasif) → 整えられつつある.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita keuangan berikut. Apa tren yang dilaporkan?', '{"audio_text":"若年層を中心に、長期的な資産形成への関心が急速に高まりつつあります。","options":[{"id":"opt_1","text":"Minat terhadap pembentukan aset jangka panjang sedang naik pesat terutama di kalangan muda"},{"id":"opt_2","text":"Kalangan muda berhenti menabung dan berinvestasi sepenuhnya"},{"id":"opt_3","text":"Suku bunga pinjaman perumahan naik tiga kali lipat bulan ini"},{"id":"opt_4","text":"Perusahaan sekuritas menutup seluruh layanan daringnya"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '若年層 (kalangan usia muda) dan 資産形成 (pembentukan aset/investasi).', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan teknologi berikut. Apa yang sedang terwujud?', '{"audio_text":"これまでSFの世界の話と思われていた技術が、今まさに現実のものとなりつつある。","options":[{"id":"opt_1","text":"Teknologi baru gagal diuji coba di laboratorium"},{"id":"opt_2","text":"Film fiksi ilmiah dilarang tayang di bioskop"},{"id":"opt_3","text":"Teknologi yang dulu dianggap fiksi ilmiah kini sedang menjadi kenyataan"},{"id":"opt_4","text":"Para ilmuwan menghentikan riset kecerdasan buatan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '現実のものとなりつつある berarti sedang berubah menjadi kenyataan.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Penggunaan kertas di kantor sedang berkurang berkat digitalisasi."', '{"tokens":["ある。","減少","デジタル化により、","オフィスでの","しつつ","減少した","にあたって","紙の使用量が"],"target_translation":"Penggunaan kertas di kantor sedang berkurang berkat digitalisasi.","romaji":"Dejitaruka ni yori, ofisu de no kami no shiyouryou ga genshou shitsutsu aru."}'::jsonb, '["デジタル化により、","オフィスでの","紙の使用量が","減少","しつつ","ある。"]'::jsonb, '使用量 (jumlah pemakaian) dan 減少 (berkurang) sangat umum dalam laporan perusahaan.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Persiapan untuk menyambut acara internasional tahun depan sedang berjalan lancar."', '{"display_text":"来年の国際大会に向けた準備が、着々と進みつつあります。","romaji":"Rainen no kokusai taikai ni muketa junbi ga, chakuchaku to susumitsutsu arimasu.","phonetic_breakdown":["らいねんの","こくさいたいかいに","むけたじゅんびが","ちゃくちゃくと","すすみつつあります"]}'::jsonb, '{"expected_transcript":"来年の国際大会に向けた準備が、着々と進みつつあります。"}'::jsonb, '着々と (chakuchaku to) berarti langkah demi langkah secara mantap.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 小さな確認ミスが、重大な___を引き起こしかねない。', '{"options":["事故","歓迎","卒業","普及"],"translation":"Kesalahan pengecekan kecil bisa saja memicu kecelakaan serius.","sentence_template":"小さな確認ミスが、重大な[blank]を引き起こしかねない。"}'::jsonb, '{"selected":"事故"}'::jsonb, '重大な事故を引き起こす berarti memicu kecelakaan serius; konteks negatif khas ～かねない.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat peringatan bisnis berikut: 不適切な対応を続ければ、企業の___を損ないかねない。', '{"options":["信用","気候","趣味","季節"],"translation":"Jika terus memberikan penanganan yang tidak tepat, hal itu bisa saja merusak kredibilitas perusahaan.","sentence_template":"不適切な対応を続ければ、企業の[blank]を損ないかねない。"}'::jsonb, '{"selected":"信用"}'::jsonb, '信用を損なう (merusak kredibilitas/kepercayaan) adalah kolokasi penting bisnis N2.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: パスワードの使い回しは、個人情報の___につながりかねない。', '{"options":["漏洩","設立","開会","回復"],"translation":"Menggunakan kata sandi yang sama berulang kali bisa saja berujung pada kebocoran data pribadi.","sentence_template":"パスワードの使い回しは、個人情報の[blank]につながりかねない。"}'::jsonb, '{"selected":"漏洩"}'::jsonb, '漏洩 (rouei) berarti kebocoran informasi atau data.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan peringatan manajer keselamatan berikut. Risiko apa yang dikhawatirkan?', '{"audio_text":"機械の点検を怠ると、作業員が大けがをしかねないので徹底してください。","options":[{"id":"opt_1","text":"Pekerja bisa saja mengalami cedera berat jika pemeriksaan mesin diabaikan"},{"id":"opt_2","text":"Mesin akan bekerja dua kali lebih cepat dari biasanya"},{"id":"opt_3","text":"Biaya listrik pabrik akan turun drastis bulan ini"},{"id":"opt_4","text":"Jadwal libur pekerja akan ditambah seminggu"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '点検を怠る (melalaikan inspeksi) → 大けがをしかねない (bisa saja mengalami cedera serius).', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan nasihat rekan kerja berikut. Mengapa ia mengingatkan soal cara bicara?', '{"audio_text":"その言い方だと、相手に誤解を与えかねないから表現を変えたほうがいいよ。","options":[{"id":"opt_1","text":"Karena kalimatnya terlalu pendek untuk laporan resmi"},{"id":"opt_2","text":"Karena cara bicara seperti itu bisa saja menimbulkan kesalahpahaman"},{"id":"opt_3","text":"Karena lawan bicara tidak mengerti istilah teknis komputer"},{"id":"opt_4","text":"Karena suara pembicara terlalu pelan di ruang rapat"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '誤解を与えかねない berarti ''bisa saja menimbulkan kesalahpahaman''.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika terus bekerja tanpa istirahat, Anda bisa saja jatuh sakit."', '{"display_text":"休息を取らずに働き続けると、体調を崩しかねませんよ。","romaji":"Kyuusoku o torazu ni hataraki tsuzukeru to, taichou o kuzushikanemasen yo.","phonetic_breakdown":["きゅうそくを","とらずに","はたらきつづけると","たいちょうを","くずしかねませんよ"]}'::jsonb, '{"expected_transcript":"休息を取らずに働き続けると、体調を崩しかねませんよ。"}'::jsonb, '体調を崩す (jatuh sakit/kondisi fisik menurun) → 崩しかねない.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi konjugasi yang benar: このまま赤字が続けば、会社は倒産___かねない。', '{"options":["し","する","した","して"],"translation":"Jika defisit terus berlanjut seperti ini, perusahaan bisa saja bangkrut.","sentence_template":"このまま赤字が続けば、会社は倒産[blank]かねない。"}'::jsonb, '{"selected":"し"}'::jsonb, 'Pola ～かねない menempel pada akar bentuk ます (倒産する → 倒産し + かねない).', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk risiko negatif: 噂を軽率に広めると、深刻なトラブルに発展___。', '{"options":["しかねない","しつつある","するにあたって","するに限らず"],"translation":"Jika menyebarkan rumor secara gegabah, hal itu bisa saja berkembang menjadi masalah serius.","sentence_template":"噂を軽率に広めると、深刻なトラブルに発展[blank]。"}'::jsonb, '{"selected":"しかねない"}'::jsonb, '～かねない khusus digunakan untuk kemungkinan terjadinya hal buruk/tidak diinginkan.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk verba Godan berikut: 準備不足のまま発表すれば、質問に答えられず恥を___かねない。', '{"options":["かき","かく","かいた","かいて"],"translation":"Jika presentasi tanpa persiapan cukup, kita bisa saja malu karena tak mampu menjawab pertanyaan.","sentence_template":"準備不足のまま発表すれば、質問に答えられず恥を[blank]かねない。"}'::jsonb, '{"selected":"かき"}'::jsonb, '恥をかく (mendapat malu) → akar ます adalah 恥をかき → 恥をかきかねない.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Keterlambatan pengiriman bisa saja memicu pembatalan kontrak."', '{"tokens":["解除を","契約の","遅れは、","納期の","つつある。","招く","かねない。","招き"],"target_translation":"Keterlambatan pengiriman bisa saja memicu pembatalan kontrak.","romaji":"Nouki no okure wa, keiyaku no kaijo o manekikanenai."}'::jsonb, '["納期の","遅れは、","契約の","解除を","招き","かねない。"]'::jsonb, '招く (mengundang/memicu dampak buruk) → 招きかねない.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Mengemudi dalam keadaan mengantuk bisa saja menyebabkan kecelakaan fatal."', '{"tokens":["にあたって。","かねない。","居眠り運転は、","引き起こし","命に関わる","事故を","引き起こす"],"target_translation":"Mengemudi dalam keadaan mengantuk bisa saja menyebabkan kecelakaan fatal.","romaji":"Inemuri unten wa, inochi ni kakawaru jiko o hikiokoshikanenai."}'::jsonb, '["居眠り運転は、","命に関わる","事故を","引き起こし","かねない。"]'::jsonb, '命に関わる事故 (kecelakaan yang mengancam nyawa) + 引き起こしかねない.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika data tidak dicadangkan, dokumen penting bisa saja hilang seluruhnya."', '{"display_text":"バックアップを取らないと、重要なデータがすべて消えかねません。","romaji":"Bakkuappu o toranai to, juuyouna deeta ga subete kiekanemasen.","phonetic_breakdown":["ばっくあっぷを","とらないと","じゅうような","でーたがすべて","きえかねません"]}'::jsonb, '{"expected_transcript":"バックアップを取らないと、重要なデータがすべて消えかねません。"}'::jsonb, '消える (Ichidan) → 消えかねない (bisa saja hilang).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan komentar analis ekonomi berikut. Risiko apa yang ia soroti?', '{"audio_text":"急速な利上げが続けば、中小企業の経営を圧迫しかねないという懸念が広がっている。","options":[{"id":"opt_1","text":"Kenaikan suku bunga cepat bisa saja menekan keuangan usaha kecil dan menengah"},{"id":"opt_2","text":"Usaha kecil dan menengah akan memperoleh keuntungan berlipat"},{"id":"opt_3","text":"Bank sentral akan menurunkan suku bunga hingga nol persen"},{"id":"opt_4","text":"Ekspor produk pertanian akan meningkat tajam bulan depan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '経営を圧迫しかねない berarti bisa saja menekan/memberatkan operasional bisnis.', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman IT kantor berikut. Mengapa karyawan dilarang membuka tautan mencurigakan?', '{"audio_text":"不審なメールのリンクを開くと、社内ネットワーク全体がウイルスに感染しかねないからです。","options":[{"id":"opt_1","text":"Karena ukuran lampiran email terlalu besar untuk kotak masuk"},{"id":"opt_2","text":"Karena komputer hanya perlu dihidupkan ulang sekali sehari"},{"id":"opt_3","text":"Karena seluruh jaringan internal kantor bisa saja terinfeksi virus"},{"id":"opt_4","text":"Karena koneksi internet kantor akan menjadi lebih cepat"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'ウイルスに感染しかねない berarti ''bisa saja terinfeksi virus''.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan ucapan dosen berikut. Apa yang ia peringatkan kepada mahasiswa?', '{"audio_text":"出典を明記せずに文章を引用すると、盗用とみなされかねないので注意してください。","options":[{"id":"opt_1","text":"Nilai makalah akan otomatis mendapat bonus tambahan"},{"id":"opt_2","text":"Makalah akan langsung diterbitkan di jurnal internasional"},{"id":"opt_3","text":"Jumlah halaman makalah akan berkurang dari batas minimal"},{"id":"opt_4","text":"Tindakan itu bisa saja dianggap sebagai plagiarisme"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '盗用 (touyou, plagiarisme) + みなされかねない (bisa saja dianggap sebagai).', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予算を削りすぎると、製品の品質低下を___かねない。', '{"options":["招き","招く","招いた","招いて"],"translation":"Jika anggaran dipangkas terlalu banyak, hal itu bisa saja mengundang penurunan kualitas produk.","sentence_template":"予算を削りすぎると、製品の品質低下を[blank]かねない。"}'::jsonb, '{"selected":"招き"}'::jsonb, '招く (Godan) → 招きかねない.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 彼は感情的になると、何を言い出すか分からないので、会議で暴言を___かねない。', '{"options":["吐き","吐く","吐いた","吐いて"],"translation":"Karena jika emosional tidak jelas apa yang akan ia katakan, ia bisa saja melontarkan kata-kata kasar di rapat.","sentence_template":"彼は感情的になると、何を言い出すか分からないので、会議で暴言を[blank]かねない。"}'::jsonb, '{"selected":"吐き"}'::jsonb, '暴言を吐く (melontarkan kata-kata kasar) → 吐きかねない.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Keputusan yang tergesa-gesa bisa saja menimbulkan kerugian besar di kemudian hari."', '{"display_text":"性急な判断は、後で大きな損失を生みかねません。","romaji":"Seikyuuna handan wa, ato de ookina sonshitsu o umikanemasen.","phonetic_breakdown":["せいきゅうな","はんだんは","あとで","おおきなそんしつを","うみかねません"]}'::jsonb, '{"expected_transcript":"性急な判断は、後で大きな損失を生みかねません。"}'::jsonb, '性急な (tergesa-gesa) dan 損失を生む (menimbulkan kerugian) adalah kosakata bisnis N2.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika informasi bocor, perusahaan bisa saja kehilangan kepercayaan klien."', '{"tokens":["つつある。","情報が","漏れれば、","かねない。","顧客からの","失う","失い","信頼を"],"target_translation":"Jika informasi bocor, perusahaan bisa saja kehilangan kepercayaan klien.","romaji":"Jouhou ga morereba, kokyaku kara no shinrai o ushinaikanenai."}'::jsonb, '["情報が","漏れれば、","顧客からの","信頼を","失い","かねない。"]'::jsonb, '失う (kehilangan) → 失いかねない.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika aturan keselamatan diabaikan, kecelakaan kerja bisa saja terjadi."', '{"tokens":["軽視すれば、","発生する","しかねない。","労働災害が","にあたって。","安全規則を","発生"],"target_translation":"Jika aturan keselamatan diabaikan, kecelakaan kerja bisa saja terjadi.","romaji":"Anzen kisoku o keishi sureba, roudou saigai ga hassei shikanenai."}'::jsonb, '["安全規則を","軽視すれば、","労働災害が","発生","しかねない。"]'::jsonb, '軽視する (meremehkan) dan 労働災害 (kecelakaan kerja).', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kurangnya komunikasi bisa saja menyebabkan keterlambatan seluruh proyek."', '{"tokens":["つながる","つながり","プロジェクト全体の","遅延に","に限らず。","かねない。","連絡不足は、"],"target_translation":"Kurangnya komunikasi bisa saja menyebabkan keterlambatan seluruh proyek.","romaji":"Renraku busoku wa, purojekuto zentai no chien ni tsunagarikanenai."}'::jsonb, '["連絡不足は、","プロジェクト全体の","遅延に","つながり","かねない。"]'::jsonb, '～につながりかねない berarti ''bisa saja berujung pada...''.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika tidak segera diperbaiki, kerusakan kecil ini bisa saja meluas."', '{"display_text":"早めに修理しないと、この小さな故障が広がりかねません。","romaji":"Hayame ni shuuri shinai to, kono chiisana koshou ga hirogarikanemasen.","phonetic_breakdown":["はやめに","しゅうりしないと","このちいさな","こしょうが","ひろがりかねません"]}'::jsonb, '{"expected_transcript":"早めに修理しないと、この小さな故障が広がりかねません。"}'::jsonb, '早めに (lebih awal/segera) + 広がりかねない (bisa saja meluas).', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pernyataan yang tidak akurat bisa saja memicu kepanikan di pasar."', '{"display_text":"不正確な発表は、市場の混乱を招きかねません。","romaji":"Fuseikakuna happyou wa, shijou no konran o manekikanemasen.","phonetic_breakdown":["ふせいかくな","はっぴょうは","しじょうのこんらんを","まねきかねません"]}'::jsonb, '{"expected_transcript":"不正確な発表は、市場の混乱を招きかねません。"}'::jsonb, '市場の混乱 (kekacauan pasar) sering muncul dalam berita ekonomi.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika terus menunda keputusan, kita bisa saja kehilangan peluang bisnis terbaik."', '{"display_text":"決断を先延ばしにすると、絶好のビジネスチャンスを逃しかねません。","romaji":"Ketsudan o sakinobashi ni suru to, zekkou no bijinesu chansu o nogashikanemasen.","phonetic_breakdown":["けつだんを","さきのばしにすると","ぜっこうの","びじねすちゃんすを","のがしかねません"]}'::jsonb, '{"expected_transcript":"決断を先延ばしにすると、絶好のビジネスチャンスを逃しかねません。"}'::jsonb, 'チャンスを逃す (melewatkan peluang) → 逃しかねない.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 衛生管理が不十分だと、食中毒を___かねない。', '{"options":["引き起こし","引き起こす","引き起こした","引き起こして"],"translation":"Jika manajemen kebersihan kurang memadai, hal itu bisa saja menyebabkan keracunan makanan.","sentence_template":"衛生管理が不十分だと、食中毒を[blank]かねない。"}'::jsonb, '{"selected":"引き起こし"}'::jsonb, '引き起こす (Godan) → akar ます adalah 引き起こし → 引き起こしかねない.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 過密なスケジュールを強行すれば、社員の離職率が___。', '{"options":["上昇しかねない","上昇するにあたって","上昇するに限らず","上昇した上で"],"translation":"Jika memaksakan jadwal yang terlalu padat, tingkat pengunduran diri karyawan bisa saja meningkat.","sentence_template":"過密なスケジュールを強行すれば、社員の離職率が[blank]。"}'::jsonb, '{"selected":"上昇しかねない"}'::jsonb, '離職率 (tingkat turnover/resign karyawan) + 上昇しかねない.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan peringatan berikut. Apa dampak buruk yang dikhawatirkan?', '{"audio_text":"このまま資源の浪費を続ければ、将来の世代に深刻な負担を残しかねない。","options":[{"id":"opt_1","text":"Bisa saja meninggalkan beban serius bagi generasi mendatang"},{"id":"opt_2","text":"Sumber daya alam akan bertambah dua kali lipat"},{"id":"opt_3","text":"Biaya energi akan menjadi gratis dalam lima tahun"},{"id":"opt_4","text":"Generasi mendatang tidak perlu lagi bekerja"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '資源の浪費 (pemborosan sumber daya) → 深刻な負担を残しかねない.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan diskusi rapat berikut. Mengapa mereka berhati-hati merilis fitur baru?', '{"audio_text":"十分なテストをせずに公開すると、利用者の離脱につながりかねないからです。","options":[{"id":"opt_1","text":"Karena jumlah pengguna baru akan langsung membludak"},{"id":"opt_2","text":"Karena bisa saja menyebabkan pengguna meninggalkan layanan"},{"id":"opt_3","text":"Karena biaya server akan turun terlalu rendah"},{"id":"opt_4","text":"Karena tim pemasaran belum menyiapkan logo baru"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '利用者の離脱 (pengguna pergi/churn) + つながりかねない.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kesalahan penerjemahan dalam kontrak bisa saja memicu sengketa hukum."', '{"tokens":["法的トラブルに","誤訳は、","発展する","つつある。","契約書の","発展","しかねない。"],"target_translation":"Kesalahan penerjemahan dalam kontrak bisa saja memicu sengketa hukum.","romaji":"Keiyakusho no goyaku wa, houteki toraburu ni hatten shikanenai."}'::jsonb, '["契約書の","誤訳は、","法的トラブルに","発展","しかねない。"]'::jsonb, '誤訳 (kesalahan terjemahan) dan 法的トラブル (masalah hukum).', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Ketidakpastian informasi bisa saja menimbulkan kecemasan di kalangan karyawan."', '{"display_text":"情報共有の遅れは、社内に不要な不安を広げかねません。","romaji":"Jouhou kyouyuu no okure wa, shanai ni fuyouna fuan o hirogekanemasen.","phonetic_breakdown":["じょうほうきょうゆうの","おくれは","しゃないに","ふようなふあんを","ひろげかねません"]}'::jsonb, '{"expected_transcript":"情報共有の遅れは、社内に不要な不安を広げかねません。"}'::jsonb, '広げる (Ichidan, menyebarkan) → 広げかねない.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index)
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang tepat untuk 見る: 部長、先ほどお送りした資料はすでに___になりましたか。', '{"options":["ご覧","拝見","お見","ご見"],"translation":"Pak Kepala Departemen, apakah Bapak sudah melihat materi yang saya kirimkan tadi?","sentence_template":"部長、先ほどお送りした資料はすでに[blank]になりましたか。"}'::jsonb, '{"selected":"ご覧"}'::jsonb, 'Sonkeigo khusus dari 見る adalah ご覧になる (sedangkan 拝見する adalah Kenjougo untuk diri sendiri).', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang tepat untuk 言う: 社長が___とおりに、企画書を修正いたしました。', '{"options":["おっしゃった","申した","伺った","いただいた"],"translation":"Saya telah merevisi proposal sesuai dengan apa yang disampaikan oleh Direktur Utama.","sentence_template":"社長が[blank]とおりに、企画書を修正いたしました。"}'::jsonb, '{"selected":"おっしゃった"}'::jsonb, 'Sonkeigo dari 言う adalah おっしゃる (lampau: おっしゃった).', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang tepat untuk いる/行く/来る: ただいま専務は会議室に___。', '{"options":["いらっしゃいます","まいります","おります","いたします"],"translation":"Saat ini Direktur Pelaksana sedang berada di ruang rapat.","sentence_template":"ただいま専務は会議室に[blank]。"}'::jsonb, '{"selected":"いらっしゃいます"}'::jsonb, 'いらっしゃる adalah bentuk Sonkeigo untuk いる, 行く, dan 来る.', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan resepsionis kantor berikut. Di mana Presiden Direktur berada sekarang?', '{"audio_text":"申し訳ございません。社長はただいま外出していらっしゃいます。","options":[{"id":"opt_1","text":"Sedang keluar kantor saat ini"},{"id":"opt_2","text":"Sedang makan siang di kantin lantai dua"},{"id":"opt_3","text":"Sedang menerima tamu di ruang resepsionis"},{"id":"opt_4","text":"Sudah pulang ke rumah sejak pagi tadi"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '外出していらっしゃいます menggunakan ～ていらっしゃる untuk meninggikan aksi atasan.', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan kalimat di ruang tamu klien berikut. Apa yang ditawarkan staf?', '{"audio_text":"よろしければ、こちらのお茶をどうぞ召し上がってください。","options":[{"id":"opt_1","text":"Meminta tamu membawa pulang dokumen kontrak"},{"id":"opt_2","text":"Mempersilakan tamu meminum teh yang disediakan"},{"id":"opt_3","text":"Menanyakan jadwal keberangkatan pesawat tamu"},{"id":"opt_4","text":"Meminta tamu menunggu di lobi lantai bawah"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '召し上がる (meshiagaru) adalah bentuk Sonkeigo baku untuk 食べる dan 飲む.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Bapak sudah memeriksa email yang saya kirim kemarin?"', '{"display_text":"昨日お送りしたメールはご覧になりましたでしょうか。","romaji":"Kinou ookuri shita meeru wa goran ni narimashita deshou ka.","phonetic_breakdown":["きのう","おおくりした","めーるは","ごらんに","なりましたでしょうか"]}'::jsonb, '{"expected_transcript":"昨日お送りしたメールはご覧になりましたでしょうか。"}'::jsonb, 'ご覧になりましたでしょうか sangat sopan untuk menanyakan apakah klien/atasan sudah membaca email.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pola Sonkeigo お + V-ます stem + になる: お客様はもう会場に___になりました。', '{"options":["お着き","お着く","お着いた","お着いて"],"translation":"Tamu sudah tiba di lokasi acara.","sentence_template":"お客様はもう会場に[blank]になりました。"}'::jsonb, '{"selected":"お着き"}'::jsonb, 'Pola お + [Akar ます] + になる: 着く → お着きになる.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang benar untuk kata kerja する (kango): 田中様はこちらの資料をすでに___ましたか。', '{"options":["ご確認なさい","ご確認いたし","ご確認申し","ご確認参り"],"translation":"Apakah Bapak Tanaka sudah memeriksa dokumen ini?","sentence_template":"田中様はこちらの資料をすでに[blank]ましたか。"}'::jsonb, '{"selected":"ご確認なさい"}'::jsonb, 'ご + [Nomina Kango] + なさる adalah pola Sonkeigo yang sangat baku (konjugasi ます: なさいます).', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo dari 知っている: 部長は今度の人事異動について___ですか。', '{"options":["ご存じ","存じ上げ","お知り","ご承知いたし"],"translation":"Apakah Bapak Kepala Departemen mengetahui mengenai mutasi personalia kali ini?","sentence_template":"部長は今度の人事異動について[blank]ですか。"}'::jsonb, '{"selected":"ご存じ"}'::jsonb, 'Sonkeigo dari 知っている adalah ご存じです (sedangkan 存じ上げる adalah Kenjougo).', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bapak Presiden Direktur sudah pulang ke rumah sekitar pukul lima."', '{"tokens":["お帰りに","五時ごろ","参り","お帰りいたし","ました。","なり","社長は"],"target_translation":"Bapak Presiden Direktur sudah pulang ke rumah sekitar pukul lima.","romaji":"Shachou wa goji goro okaeri ni narimashita."}'::jsonb, '["社長は","五時ごろ","お帰りに","なり","ました。"]'::jsonb, '帰る → お帰りになる adalah bentuk Sonkeigo yang tepat untuk atasan.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Silakan duduk di kursi sebelah sini sambil menunggu."', '{"tokens":["ください。","こちらの","掛けいたし","どうぞ","お席に","お掛け","参って"],"target_translation":"Silakan duduk di kursi sebelah sini sambil menunggu.","romaji":"Douzo kochira no oseki ni okake kudasai."}'::jsonb, '["どうぞ","こちらの","お席に","お掛け","ください。"]'::jsonb, 'お掛けください (dari 腰掛ける) adalah ungkapan baku mempersilakan tamu duduk.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika ada pertanyaan, silakan bertanya kapan saja."', '{"display_text":"ご不明な点がございましたら、いつでもお尋ねください。","romaji":"Gofumei na ten ga gozaimashitara, itsudemo otazune kudasai.","phonetic_breakdown":["ごふめいなてんが","ございましたら","いつでも","おたずねください"]}'::jsonb, '{"expected_transcript":"ご不明な点がございましたら、いつでもお尋ねください。"}'::jsonb, 'お尋ねください berarti ''silakan bertanya'' dengan tingkat kesopanan bisnis baku.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan telepon bisnis berikut. Kapan Ibu Sato akan kembali?', '{"audio_text":"佐藤はただいま席を外しておりますが、まもなくお戻りになる予定です。","options":[{"id":"opt_1","text":"Ibu Sato tidak masuk kerja hari ini"},{"id":"opt_2","text":"Ibu Sato sedang meninggalkan meja sebentar dan akan segera kembali"},{"id":"opt_3","text":"Ibu Sato sedang dinas ke luar negeri hingga minggu depan"},{"id":"opt_4","text":"Ibu Sato sedang memindahkan ruang kerjanya ke lantai atas"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '席を外しております (sedang meninggalkan meja) dan お戻りになる (akan kembali).', 1),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan ucapan moderator seminar berikut. Siapa yang akan berbicara selanjutnya?', '{"audio_text":"続きまして、山田教授にご講演をいただきます。先生、よろしくお願いいたします。","options":[{"id":"opt_1","text":"Direktur keuangan dari perusahaan sponsor"},{"id":"opt_2","text":"Perwakilan mahasiswa tingkat pertama"},{"id":"opt_3","text":"Profesor Yamada yang akan memberikan ceramah"},{"id":"opt_4","text":"Staf administrasi penyelenggara seminar"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'ご講演をいただく adalah bentuk sopan mempersilakan pembicara menyampaikan kuliah/ceramah.', 2),
        (gen_random_uuid(), v_lesson_id, NULL, 'listening', 'listening_choice', 'Dengarkan percakapan di kantor berikut. Apa yang ditanyakan kepada klien?', '{"audio_text":"お帰りの際、お忘れ物のないよう今一度お手回り品をご確認くださいますでしょうか。","options":[{"id":"opt_1","text":"Menanyakan alamat pengiriman katalog produk baru"},{"id":"opt_2","text":"Meminta klien mengisi formulir survei kepuasan"},{"id":"opt_3","text":"Menanyakan apakah klien ingin memesan taksi ke bandara"},{"id":"opt_4","text":"Mengingatkan klien memeriksa barang bawaan agar tidak ada yang tertinggal"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, 'お手回り品 (barang bawaan pribadi) dan ご確認くださいますでしょうか (mohon berkenan memeriksa).', 3),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang tepat (hindari salah tukar dengan Kenjougo): 先生、明日何時ごろ大学へ___ますか。', '{"options":["いらっしゃい","参り","伺い","いたし"],"translation":"Sensei, besok sekitar pukul berapa Bapak/Ibu datang ke universitas?","sentence_template":"先生、明日何時ごろ大学へ[blank]ますか。"}'::jsonb, '{"selected":"いらっしゃい"}'::jsonb, 'Untuk menanyakan kedatangan guru/atasan, gunakan いらっしゃいます (bukan 参ります atau 伺います yang merupakan Kenjougo).', 4),
        (gen_random_uuid(), v_lesson_id, NULL, 'reading', 'fill_blank', 'Lengkapi email bisnis berikut: 先日___いただいた件につきまして、社内で検討いたしました。', '{"options":["ご相談","お聞き","拝見","お伺い"],"translation":"Mengenai hal yang tempo hari Anda konsultasikan kepada kami, kami telah membahasnya di internal.","sentence_template":"先日[blank]いただいた件につきまして、社内で検討いたしました。"}'::jsonb, '{"selected":"ご相談"}'::jsonb, 'ご相談いただいた件 merujuk pada konsultasi/permintaan yang datang dari pihak klien.', 5),
        (gen_random_uuid(), v_lesson_id, NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kapan Bapak/Ibu berencana berkunjung ke kantor kami?"', '{"display_text":"いつごろ弊社へお越しになるご予定でしょうか。","romaji":"Itsugoro heisha e okoshi ni naru goyotei deshou ka.","phonetic_breakdown":["いつごろ","へいしゃえ","おこしになる","ごよていでしょうか"]}'::jsonb, '{"expected_transcript":"いつごろ弊社へお越しになるご予定でしょうか。"}'::jsonb, '弊社 (perusahaan kami, bentuk merendah) dan お越しになる (datang, Sonkeigo baku).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Ibu Kepala Bagian sudah membaca laporan hari ini?"', '{"tokens":["報告書を","お読みに","課長は","お読みいたし","本日の","なりましたか。","拝見し"],"target_translation":"Apakah Ibu Kepala Bagian sudah membaca laporan hari ini?","romaji":"Kachou wa honjitsu no houkokusho o oyomi ni narimashita ka."}'::jsonb, '["課長は","本日の","報告書を","お読みに","なりましたか。"]'::jsonb, '読む → お読みになる adalah bentuk Sonkeigo yang benar untuk atasan.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Klien telah menyetujui syarat yang kami ajukan kemarin."', '{"tokens":["なさいました。","お客様は","ご承諾いたし","申し上げ","昨日の","ご承諾","条件を"],"target_translation":"Klien telah menyetujui syarat yang kami ajukan kemarin.","romaji":"Okyakusama wa kinou no jouken o goshoudaku nasaimashita."}'::jsonb, '["お客様は","昨日の","条件を","ご承諾","なさいました。"]'::jsonb, '承諾する (menyetujui) → ご承諾なさる.', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Bapak mengenal penanggung jawab dari kantor cabang Osaka?"', '{"tokens":["おり","ご担当者を","でいらっしゃい","ますか。","存じ上げて","ご存じ","大阪支店の"],"target_translation":"Apakah Bapak mengenal penanggung jawab dari kantor cabang Osaka?","romaji":"Oosaka shiten no gotantousha o gozonji de irasshaimasu ka."}'::jsonb, '["大阪支店の","ご担当者を","ご存じ","でいらっしゃい","ますか。"]'::jsonb, 'ご存じでいらっしゃいますか adalah bentuk Sonkeigo yang sangat sopan dari 知っていますか.', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mohon maaf telah membuat Anda menunggu cukup lama."', '{"display_text":"大変お待たせいたしました。どうぞ中へお入りください。","romaji":"Taihen omatase itashimashita. Douzo naka e ohairi kudasai.","phonetic_breakdown":["たいへん","おまたせいたしました","どうぞなかえ","おはいりください"]}'::jsonb, '{"expected_transcript":"大変お待たせいたしました。どうぞ中へお入りください。"}'::jsonb, 'お待たせいたしました (Kenjougo) + お入りください (Sonkeigo) adalah kombinasi standar penyambutan tamu.', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih telah meluangkan waktu untuk hadir hari ini."', '{"display_text":"本日はお忙しい中お越しくださり、誠にありがとうございます。","romaji":"Honjitsu wa oisogashii naka okoshi kudasari, makoto ni arigatou gozaimasu.","phonetic_breakdown":["ほんじつは","おいそがしいなか","おこしくださり","まことに","ありがとうございます"]}'::jsonb, '{"expected_transcript":"本日はお忙しい中お越しくださり、誠にありがとうございます。"}'::jsonb, 'お越しくださり adalah bentuk sangat sopan dari 来てくれて.', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Anda ingin memesan kopi atau teh hijau?"', '{"display_text":"お飲み物はコーヒーと緑茶のどちらになさいますか。","romaji":"Onomimono wa koohii to ryokucha no dochira ni nasaimasu ka.","phonetic_breakdown":["おのみものは","こーひーと","りょくちゃの","どちらに","なさいますか"]}'::jsonb, '{"expected_transcript":"お飲み物はコーヒーと緑茶のどちらになさいますか。"}'::jsonb, 'どちらになさいますか adalah bentuk Sonkeigo dari どちらにしますか saat menawarkan pilihan kepada tamu.', 6);
