    VALUES
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih Sonkeigo yang tepat: 社長が明日の式典でご挨拶を___予定です。', '{"options":["なさる","いたす","申す","伺う"],"translation":"Direktur Utama dijadwalkan memberikan kata sambutan pada upacara besok.","sentence_template":"社長が明日の式典でご挨拶を[blank]予定です。"}'::jsonb, '{"selected":"なさる"}'::jsonb, 'ご挨拶をなさる menggunakan なさる (Sonkeigo dari する) untuk meninggikan tindakan Direktur Utama.', 1),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat gabungan N2 berikut: 新規事業の発足___、社長より今後の展望についてお話がございました。', '{"options":["にあたり","かねない","つつある","ざるを得ない"],"translation":"Pada kesempatan peluncuran bisnis baru, ada sambutan dari Direktur Utama mengenai prospek ke depan.","sentence_template":"新規事業の発足[blank]、社長より今後の展望についてお話がございました。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, 'Menggabungkan pola Unit 1 (～にあたり) dan bahasa hormat Unit 10 (お話がございました).', 2),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan bisnis berikut. Apa yang akan dilakukan pembicara setelah ini?', '{"audio_text":"お客様がお帰りになりましたら、すぐに応接室の片付けをしてまいります。","options":[{"id":"opt_1","text":"Merapikan ruang tamu segera setelah klien pulang"},{"id":"opt_2","text":"Mengantar klien ke bandara dengan mobil perusahaan"},{"id":"opt_3","text":"Memesan makan siang untuk rapat sore"},{"id":"opt_4","text":"Menghubungi cabang luar negeri lewat telepon"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'お帰りになりましたら (Sonkeigo untuk klien) diikuti してまいります (Kenjougo untuk diri sendiri).', 3),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan sambutan penutup berikut. Apa harapan pembicara?', '{"audio_text":"本日の会議でご提案いただいた内容を踏まえ、今後も皆様と協力して発展してまいりたいと存じます。","options":[{"id":"opt_1","text":"Menghentikan kerja sama setelah proyek ini selesai"},{"id":"opt_2","text":"Menunda pembahasan usulan hingga tahun depan"},{"id":"opt_3","text":"Terus berkembang bersama seluruh pihak berdasarkan usulan yang diterima hari ini"},{"id":"opt_4","text":"Memindahkan seluruh kegiatan rapat ke sistem daring"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'ご提案いただいた内容 (isi usulan yang Anda berikan) + 発展してまいりたいと存じます (kami ingin terus berkembang bersama).', 4),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Bapak Profesor sudah menerima surat undangan dari kami?"', '{"tokens":["申し上げ","お受け取りに","私どもの","先生は","なりましたか。","案内状を","お受け取りいたし"],"target_translation":"Apakah Bapak Profesor sudah menerima surat undangan dari kami?","romaji":"Sensei wa watakushidomo no annaijou o ouketori ni narimashita ka."}'::jsonb, '["先生は","私どもの","案内状を","お受け取りに","なりましたか。"]'::jsonb, '私ども (kami, sangat sopan) dan お受け取りになる (menerima, Sonkeigo).', 5),
        (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan bekal bahasa Jepang N2 ini, saya siap berkarya secara profesional di Jepang."', '{"display_text":"この日本語力を活かして、日本の職場で活躍できるよう努力してまいります。","romaji":"Kono Nihongoryoku o ikashite, Nihon no shokuba de katsuyaku dekiru you doryoku shite mairimasu.","phonetic_breakdown":["このにほんごりょくを","いかして","にほんのしょくばで","かつやくできるよう","どりょくしてまいります"]}'::jsonb, '{"expected_transcript":"この日本語力を活かして、日本の職場で活躍できるよう努力してまいります。"}'::jsonb, 'Kalimat penutup yang sangat kuat dan alami untuk wawancara kerja profesional maupun beasiswa di Jepang.', 6);
