DO $$
DECLARE
    v_level_id uuid;
    v_unit_id uuid;
    v_lesson_id uuid;
    v_gp_id uuid;
BEGIN
    SELECT pl.id INTO v_level_id
    FROM proficiency_levels pl
    JOIN languages l ON l.id = pl.language_id
    WHERE l.code = 'ja' AND pl.code = 'N2'
    LIMIT 1;

    IF v_level_id IS NULL THEN
        RETURN;
    END IF;

    DELETE FROM units
