    -- ------------------------------------------------------------------------
    -- Unit 1: GP-JA-N2-001
    -- ------------------------------------------------------------------------
    SELECT id INTO v_gp_id FROM grammar_points WHERE code = 'GP-JA-N2-001' LIMIT 1;

