    RETURNING id INTO v_unit_id;

    VALUES (gen_random_uuid(), v_unit_id, 'Kosakata Inti Peluncuran Proyek & Acara Resmi', 'Kosakata Resmi', 'n2-u1-kosakata', 'cards', 15, 1)
